        // ================================================================= 툴팁
        { "타겟팅 스킬", L("Targeting Skill", "ターゲティングスキル", "锁定技能") },
        { "게이지가 가득 차면 우클릭을 누르고 있는 동안 시간이 느려지며 주변 적을 차례로 조준합니다.\n버튼을 떼면 조준한 모든 적에게 일제 사격!\n\n일반 사격으로 적을 맞히면 게이지가 찹니다.",
          E("게이지가 가득 차면 우클릭으로 필살기를 씁니다. 들고 있는 무기마다 조준 화면과 필살기가 다릅니다.\n\n게이지는 시간이 지나면 차고, 적을 처치하면 잠깐 더 빨리 찹니다.",
            "When the gauge is full, right-click to use your ultimate. Each weapon has its own aiming screen and ultimate.\n\nThe gauge fills over time, and faster for a moment after each kill.",
            "ゲージが満タンになったら右クリックで必殺技。武器ごとに照準画面と必殺技が違います。\n\nゲージは時間で溜まり、敵を倒すと少しの間速く溜まります。",
            "能量满时右键释放必杀技。每种武器的瞄准画面和必杀技都不同。\n\n能量随时间积累，击杀敌人后短时间内积累更快。") },

        // ================================================================= 특수 능력 (이름 · 설명)
        { "지옥불 산탄총", L("Hellfire Shotgun", "獄炎ショットガン", "狱火霰弹枪") },
        { "영혼 저격총", L("Soul Sniper", "ソウルスナイパー", "灵魂狙击枪") },
        { "저주받은 쌍권총", L("Cursed Twin Pistols", "呪われた二丁拳銃", "被诅咒的双枪") },
        { "화염 방사기", L("Flamethrower", "火炎放射器", "火焰喷射器") },
        { "영혼 인도 지팡이", L("Soulguide Staff", "魂導きの杖", "引魂法杖") },
        { "번개 사슬총", L("Chain Lightning Gun", "連鎖雷撃銃", "连锁闪电枪") },
        { "부메랑 낫", L("Boomerang Scythe", "ブーメラン鎌", "回旋镰刀") },
        { "용암 유탄 발사기", L("Lava Grenade Launcher", "溶岩グレネードランチャー", "熔岩榴弹发射器") },
        { "그림자 대시", L("Shadow Dash", "シャドウダッシュ", "暗影冲刺") },
        { "시간 왜곡", L("Time Warp", "時間歪曲", "时间扭曲") },
        { "희생의 계약", L("Blood Pact", "犠牲の契約", "牺牲契约") },
        { "영혼 폭발", L("Soul Burst", "ソウルバースト", "灵魂爆发") },
        { "해골 소환", L("Summon Skeletons", "スケルトン召喚", "召唤骷髅") },
        { "거울 분신", L("Mirror Image", "鏡の分身", "镜像分身") },
        { "피의 갈고리", L("Blood Hook", "血のフック", "鲜血钩索") },
        { "수호 영혼", L("Guardian Souls", "守護の魂", "守护之魂") },
        { "복수의 가시", L("Thorns of Vengeance", "復讐の棘", "复仇之刺") },
        { "탄창 저주", L("Cursed Magazine", "弾倉の呪い", "弹匣诅咒") },
        { "불사의 맹세", L("Oath of Undying", "不死の誓い", "不死誓约") },
        { "총알 대신 앞쪽 부채꼴(6칸) 안의 적 모두에게\n즉시 250% 피해와 강한 넉백. 발사 간격 1.4배.", L("Instead of bullets, hits every enemy in a cone ahead (6 tiles)\nfor 250% damage with strong knockback. Fire interval x1.4.", "弾の代わりに前方の扇形(6マス)内の敵全員に\n即座に250%ダメージと強いノックバック。発射間隔1.4倍。", "不发射子弹，直接对前方扇形(6格)内所有敌人\n造成250%伤害并强力击退。射击间隔1.4倍。") },
        { "누르고 있다가 떼면 발사합니다. 모든 적을 관통하고\n충전 정도에 따라 피해 60%~320%.", L("Hold and release to fire. Pierces every enemy;\n60%-320% damage depending on charge.", "押し続けて離すと発射。全ての敵を貫通し\nチャージに応じて60%〜320%ダメージ。", "按住后松开发射。穿透所有敌人，\n根据蓄力造成60%~320%伤害。") },
        { "누르고 있으면 연사합니다. 발사 간격 절반, 발당 피해 55%.\n두 발에 탄 1개만 씁니다.", L("Hold for rapid fire. Half the fire interval, 55% damage per shot.\nOnly 1 ammo per 2 shots.", "押し続けると連射。発射間隔半分、1発55%ダメージ。\n2発で弾1つしか使いません。", "按住连射。射击间隔减半，每发55%伤害。\n每2发只消耗1颗子弹。") },
        { "누르고 있으면 불을 뿜어 적을 관통하고 불태웁니다.\n탄약 대신 과열 게이지를 씁니다.", L("Hold to spew fire that pierces and burns enemies.\nUses an overheat gauge instead of ammo.", "押し続けると火を噴き、敵を貫通して燃やします。\n弾薬の代わりに過熱ゲージを使います。", "按住喷火，穿透并点燃敌人。\n使用过热槽代替弹药。") },
        { "가장 가까운 적을 쫓아가는 유도탄을 쏩니다.\n발당 피해 70%, 조준이 필요 없습니다.", L("Fires homing shots that chase the nearest enemy.\n70% damage per shot, no aiming needed.", "最も近い敵を追う誘導弾を撃ちます。\n1発70%ダメージ、照準不要。", "发射追踪最近敌人的导弹。\n每发70%伤害，无需瞄准。") },
        { "맞은 적에게서 최대 4마리에게 번개가 튑니다.\n튈 때마다 피해가 20%씩 줄어듭니다.", L("Lightning jumps from the target to up to 4 enemies.\nEach jump deals 20% less damage.", "命中した敵から最大4体に雷が飛びます。\n飛ぶたびにダメージが20%ずつ減ります。", "闪电从命中的敌人弹射到最多4个敌人。\n每次弹射伤害降低20%。") },
        { "날아갔다 돌아오며 오가는 길의 적을 모두 벱니다.\n피해 150%, 한 번에 하나만 던질 수 있습니다.", L("Flies out and back, cutting every enemy on the way.\n150% damage, only one at a time.", "飛んで戻ってくる間に道中の敵を全て斬ります。\n150%ダメージ、一度に1つだけ投げられます。", "飞出再飞回，斩击沿途所有敌人。\n150%伤害，一次只能投掷一把。") },
        { "마우스 위치에 떨어져 폭발(피해 200%)하고\n잠깐 용암 웅덩이를 남깁니다. 탄 2개 사용.", L("Lands at the cursor and explodes (200% damage),\nleaving a brief lava pool. Uses 2 ammo.", "マウス位置に落ちて爆発(200%ダメージ)し\n一時的に溶岩溜まりを残します。弾2つ使用。", "落在鼠标位置爆炸(200%伤害)，\n并短暂留下熔岩池。消耗2发弹药。") },
        { "마우스 방향으로 짧게 돌진합니다.\n돌진 중에는 무적. 쿨타임 3초.", L("Dash a short distance toward the cursor.\nInvincible while dashing. Cooldown 3s.", "マウス方向に短く突進します。\n突進中は無敵。クールタイム3秒。", "向鼠标方向短距离冲刺。\n冲刺时无敌。冷却3秒。") },
        { "마우스 위치에 4초 동안 불 장판을 깝니다.\n0.5초마다 공격력 75% 피해. 쿨타임 12초.", L("Creates a fire field at the cursor for 4s.\n75% damage every 0.5s. Cooldown 12s.", "マウス位置に4秒間炎のフィールドを敷きます。\n0.5秒ごとに攻撃力75%ダメージ。クールタイム12秒。", "在鼠标位置生成持续4秒的火焰领域。\n每0.5秒造成75%伤害。冷却12秒。") },
        { "5초 동안 모든 적이 50% 느려집니다.\n플레이어는 정상 속도. 쿨타임 20초.", L("All enemies are 50% slower for 5s.\nYou move at normal speed. Cooldown 20s.", "5秒間、全ての敵が50%遅くなります。\nプレイヤーは通常速度。クールタイム20秒。", "5秒内所有敌人减速50%。\n玩家速度不变。冷却20秒。") },
        { "최대 체력 20%를 바쳐 8초 동안\n공격력 2배, 연사 1.5배. 쿨타임 25초.", L("Sacrifice 20% max HP for 8s of\ndouble damage and x1.5 fire rate. Cooldown 25s.", "最大体力の20%を捧げ8秒間\n攻撃力2倍、連射1.5倍。クールタイム25秒。", "献祭20%最大生命，8秒内\n攻击力2倍、射速1.5倍。冷却25秒。") },
        { "적을 처치하면 영혼이 쌓입니다(최대 40).\n5개 이상일 때 모두 터뜨려 주변에 피해. 쿨타임 5초.", L("Kills store souls (max 40).\nWith 5+, detonate them all to damage nearby enemies. Cooldown 5s.", "敵を倒すと魂が溜まります(最大40)。\n5つ以上で全て炸裂させ周囲にダメージ。クールタイム5秒。", "击杀敌人积累灵魂(最多40)。\n达到5个以上时全部引爆伤害周围。冷却5秒。") },
        { "아군 해골 3기를 10초 동안 부릅니다.\n적에게 달려가 자폭(공격력 300%). 쿨타임 15초.", L("Summons 3 allied skeletons for 10s.\nThey run at enemies and explode (300%). Cooldown 15s.", "味方のスケルトン3体を10秒間呼び出します。\n敵に突っ込んで自爆(攻撃力300%)。クールタイム15秒。", "召唤3具友方骷髅，持续10秒。\n冲向敌人自爆(300%)。冷却15秒。") },
        { "제자리에 분신을 남기고 반투명해집니다.\n3초 동안 적이 분신을 쫓습니다. 쿨타임 12초.", L("Leave a decoy behind and turn translucent.\nEnemies chase the decoy for 3s. Cooldown 12s.", "その場に分身を残して半透明になります。\n3秒間、敵は分身を追います。クールタイム12秒。", "原地留下分身并变为半透明。\n敌人会追击分身3秒。冷却12秒。") },
        { "사슬을 던져 적을 끌어오거나(피해 150%)\n벽 쪽으로 날아갑니다. 쿨타임 4초.", L("Throw a chain to pull an enemy in (150%)\nor fly toward a wall. Cooldown 4s.", "鎖を投げて敵を引き寄せる(150%ダメージ)か\n壁の方へ飛びます。クールタイム4秒。", "投出锁链拉回敌人(150%伤害)\n或飞向墙壁。冷却4秒。") },
        { "영혼 구체 3개가 주위를 돌며\n닿은 적에게 공격력 80% 피해를 줍니다.", L("3 soul orbs circle you,\ndealing 80% damage to enemies they touch.", "魂の球3つが周囲を回り\n触れた敵に攻撃力80%のダメージを与えます。", "3颗灵魂球环绕你，\n对接触的敌人造成80%伤害。") },
        { "피격될 때마다 주변 적에게\n공격력 300% 피해를 주고 밀어냅니다.", L("Each time you are hit, nearby enemies\ntake 300% damage and are pushed away.", "被弾するたびに周囲の敵に\n攻撃力300%のダメージを与え押し返します。", "每次受击时对周围敌人\n造成300%伤害并击退。") },
        { "탄창의 마지막 한 발이 피해 3배가 되고\n맞은 곳에서 폭발합니다.", L("The last bullet in each magazine deals triple damage\nand explodes on impact.", "弾倉の最後の1発がダメージ3倍になり\n命中地点で爆発します。", "弹匣最后一发造成3倍伤害\n并在命中处爆炸。") },
        { "판마다 한 번, 죽을 피해를 받으면\n체력 1로 버티고 3초 동안 무적이 됩니다.", L("Once per run, survive a lethal hit\nwith 1 HP and become invincible for 3s.", "1プレイに1回、致命ダメージを受けても\n体力1で耐え、3秒間無敵になります。", "每局一次，受到致命伤害时\n以1点生命存活并无敌3秒。") },

        // ================================================================= 보스 · 스테이지
        { "킹 슬라임이 둘로 갈라졌다!", L("The King Slime split in two!", "キングスライムが二つに分裂した！", "史莱姆王分裂成了两只！") },
        { "슬라임이 또 갈라진다!", L("The slimes split again!", "スライムがまた分裂する！", "史莱姆又分裂了！") },
        { "리치 왕이 망자의 의식을 시작한다!", L("The Lich King begins the Rite of the Dead!", "リッチ王が死者の儀式を始める！", "巫妖王开始了亡者仪式！") },
