        { "불꽃 해골", L("Flame Skull", "炎のドクロ", "火焰骷髅") },
        { "가까이 오면 부풀어 오르다 폭발합니다.", L("Swells up when close, then explodes.", "近づくと膨らんで爆発する。", "靠近后膨胀并爆炸。") },
        { "지옥견", L("Hellhound", "ヘルハウンド", "地狱犬") },
        { "경로를 보여준 뒤 일직선으로 돌진합니다.", L("Shows its path, then dashes in a straight line.", "進路を示してから一直線に突進する。", "显示路线后直线冲刺。") },
        { "용암 골렘", L("Lava Golem", "溶岩ゴーレム", "熔岩魔像") },
        { "점점 넓어지는 세 번의 지면 파동을 일으킵니다.", L("Sends out three ever-widening ground shockwaves.", "だんだん広がる3回の地面の波動を起こす。", "释放三次逐渐扩大的地面冲击波。") },
        { "악마 기사", L("Demon Knight", "悪魔の騎士", "恶魔骑士") },
        { "칼날을 휘감고 회전하며 플레이어 쪽으로 미끄러집니다.", L("Spins wrapped in blades and slides toward you.", "刃をまとって回転し、プレイヤーの方へ滑り込む。", "裹挟刀刃旋转，向玩家滑行。") },
        { "초원 슬라임", L("Meadow Slime", "草原スライム", "草原史莱姆") },
        { "밟으면 아픈 산성 웅덩이를 남깁니다.", L("Leaves acid puddles that hurt to step on.", "踏むと痛い酸の水たまりを残す。", "留下踩到会受伤的酸液水洼。") },
        { "거대 벌", L("Giant Bee", "巨大バチ", "巨型蜜蜂") },
        { "플레이어 주변에 꽃가루 구름을 뿌립니다. 안에 있으면 느려지고 조금씩 피해를 입습니다.", L("Spreads pollen clouds around you. Inside, you slow down and take small damage.", "プレイヤーの周りに花粉の雲をまく。中にいると遅くなり少しずつダメージ。", "在玩家周围散布花粉云。身处其中会减速并持续受伤。") },
        { "버섯 거인", L("Mushroom Brute", "キノコの巨人", "蘑菇巨人") },
        { "주변에 버섯 지뢰를 심고 잠시 뒤 차례로 터뜨립니다.", L("Plants mushroom mines nearby that burst one after another.", "周りにキノコ地雷を植え、しばらくして順に爆発させる。", "在周围种下蘑菇地雷，片刻后依次引爆。") },
        { "다이어울프", L("Dire Wolf", "ダイアウルフ", "恐狼") },
        { "울부짖어 주변 적을 잠시 빠르게 만듭니다.", L("Howls to briefly speed up nearby enemies.", "遠吠えで周りの敵を一時的に速くする。", "嚎叫让周围的敌人暂时加速。") },
        { "트렌트", L("Treant", "トレント", "树人") },
        { "플레이어 쪽으로 뿌리 가시를 차례로 솟게 합니다.", L("Raises a line of root spikes toward you.", "プレイヤーの方へ根のトゲを次々と突き出す。", "朝玩家方向依次升起根刺。") },
        { "2장부터", L("From Stage 2", "第2章から", "第2章起") },
        { "단계가 오를 때마다 크고 단단한 적이 나타납니다. 체력 12배 · 피해 1.5배. 쓰러뜨리면 특수 능력 포인트를 줍니다.", L("A big, tough enemy appears at each new phase. 12× health · 1.5× damage. Drops a special ability point.", "段階が上がるたびに大きく硬い敵が現れる。体力12倍・ダメージ1.5倍。倒すと特殊能力ポイントがもらえる。", "每进入新阶段都会出现高大坚硬的敌人。生命×12 · 伤害×1.5。击败后获得特殊能力点。") },
        { "리치 왕", L("Lich King", "リッチ王", "巫妖王") },
        { "지옥의 군주", L("Demon Lord", "地獄の君主", "地狱领主") },
        { "킹 슬라임", L("King Slime", "キングスライム", "史莱姆王") },
        { "지하 묘역의 주인", L("Master of the Catacombs", "地下墓所の主", "地下墓穴之主") },
        { "불타는 지옥의 왕", L("King of the Burning Hell", "燃える地獄の王", "燃烧地狱之王") },
        { "초원의 폭군", L("Tyrant of the Meadow", "草原の暴君", "草原暴君") },
        { "감히 내 잠든 묘역을 깨우다니...", L("How dare you wake my sleeping catacombs...", "よくも眠れる墓所を目覚めさせたな……", "竟敢惊醒我沉睡的墓穴……") },
        { "네 영혼도 내 망자의 군대에 더해 주마!", L("Your soul shall join my army of the dead!", "貴様の魂も死者の軍勢に加えてやろう！", "你的灵魂也将加入我的亡者大军！") },
        { "하찮은 인간이 지옥의 문턱을 넘었군.", L("A worthless human has crossed the threshold of Hell.", "取るに足らぬ人間が地獄の門をくぐったか。", "卑微的人类竟跨过了地狱的门槛。") },
        { "불길 속에서 재가 되어라!", L("Burn to ashes in my flames!", "炎の中で灰となれ！", "在烈焰中化为灰烬吧！") },
        { "뿌요... 이 초원은 이 몸의 식탁이다!", L("Puyo... This meadow is my dinner table!", "ぷよ……この草原はわしの食卓だ！", "噗哟……这片草原是本大王的餐桌！") },
        { "납작하게 짓눌러 주마, 뿌요요옹!", L("I'll squash you flat, puyoyoooong!", "ぺしゃんこにしてやる、ぷよよ〜ん！", "把你压成肉饼，噗哟哟哟！") },
        { "추적 영혼구(쏴서 터뜨릴 수 있음) · 뼈 감옥(틈으로 빠져나가세요) · 저주 묘비(부수기 전까지 터짐) · 순간이동을 씁니다.\n특수: 망자의 의식 - 무적이 되어 영혼 등불 셋을 띄움. 등불을 모두 부수면 무적이 풀리고 휘청입니다 (받는 피해 1.5배)", L("Uses homing soul orbs (shoot them down), a bone prison (escape through the gap), cursed tombstones (they keep exploding until destroyed) and teleport.\nSpecial: Rite of the Dead - becomes invulnerable and raises three soul lanterns. Destroy them all to break the rite and stagger him (takes 1.5x damage)", "追尾する魂の球（撃って壊せる）・骨の牢獄（隙間から脱出）・呪いの墓石（壊すまで爆発し続ける）・瞬間移動を使います。\n特殊：死者の儀式 - 無敵になり魂の灯籠を3つ浮かべる。灯籠をすべて壊すと無敵が解け、よろめきます（受けるダメージ1.5倍）", "使用追踪灵魂球（可击破）、骨之牢笼（从缺口逃出）、诅咒墓碑（击毁前会持续爆炸）和瞬移。\n特殊：亡者仪式 - 进入无敌并召唤三盏灵魂灯。击毁所有灯后解除无敌并陷入踉跄（受到伤害1.5倍）") },
        { "3단계로 싸웁니다. 돌진 연타 · 운석 낙하 · 화염 파동(틈으로 피하세요)\n체력 66%: 날개를 펴고 공중 탄막 · 내려찍기 / 33%: 가장자리가 용암으로 좁아지고 모든 공격이 빨라짐", L("Fights in three phases: dash combos, meteor rain and fire waves (dodge through the gaps)\nAt 66% HP: spreads its wings for aerial barrages and dive slams / At 33%: lava closes in from the edges and every attack speeds up", "3段階で戦います。連続突進・隕石落下・炎の波（隙間で避けよう）\n体力66%：翼を広げ空中弾幕・急降下 / 33%：外周が溶岩で狭まり、すべての攻撃が速くなる", "分三个阶段战斗：连续冲锋、陨石坠落、火焰波（从缺口躲避）\n生命66%：展开双翼进行空中弹幕与俯冲砸地 / 33%：边缘被熔岩吞没、场地缩小，所有攻击加速") },
        { "대점프 · 점액 방울 · 구르기 돌진을 씁니다. 맞을수록 작아지고 빨라집니다.\n특수: 체력이 절반이 되면 작은 슬라임 넷을 뱉어 냄", L("Uses a big leap, slime blobs and a rolling charge. Shrinks and speeds up as it takes damage.\nSpecial: spits out four small slimes at half HP", "大ジャンプ・粘液の玉・転がり突進を使います。ダメージを受けるほど小さく速くなります。\n特殊：体力が半分になると小さなスライムを4匹吐き出す", "使用大跳跃、粘液球和翻滚冲撞。受到伤害越多体型越小、速度越快。\n特殊：生命降到一半时吐出四只小史莱姆") },
        { "마우스 쪽으로 거대한 부채꼴 폭발을 3번 연달아 일으킵니다.", L("Unleashes three huge cone-shaped blasts toward the mouse.", "マウスの方へ巨大な扇形の爆発を3連続で起こす。", "向鼠标方向连续引发三次巨大扇形爆炸。") },
        { "우클릭을 누른 채 방향을 정하면 충전 뒤 화면을 가로지르는 굵은 광선을 쏩니다. 광선 위의 적이 많을수록 강합니다.", L("Hold right-click to aim; after charging, fires a thick beam across the screen. Stronger the more enemies it hits.", "右クリックを押したまま方向を決めると、チャージ後に画面を横切る太い光線を撃つ。光線上の敵が多いほど強い。", "按住右键决定方向，充能后发射横贯屏幕的粗光束。光束上的敌人越多越强。") },
        { "두 줄기 나선으로 사방에 총알을 난사합니다. 움직이며 쓸 수 있습니다.", L("Sprays bullets everywhere in a double spiral. You can move while using it.", "2本の螺旋で四方に弾を乱射する。動きながら使える。", "以双螺旋向四周扫射子弹。可以边移动边使用。") },
        { "우클릭을 누른 채 자리를 정하면 불기둥이 생겨 적을 빨아들이고 태웁니다.", L("Hold right-click to pick a spot; a fire tornado appears, pulling in and burning enemies.", "右クリックを押したまま場所を決めると、火柱が現れて敵を吸い込み燃やす。", "按住右键选择位置，生成火焰龙卷吸入并焚烧敌人。") },
        { "영혼 구슬들이 주위를 돌다 조준한 적에게 번갈아 달려듭니다.", L("Soul orbs circle you, then take turns rushing the targeted enemies.", "魂の玉が周りを回り、狙った敵に交互に飛びかかる。", "灵魂球环绕身边，轮流冲向锁定的敌人。") },
        { "먹구름이 따라다니며 조준한 적들에게 번개를 연달아 떨어뜨립니다.", L("A storm cloud follows you, dropping lightning on the targeted enemies.", "黒雲がついてきて、狙った敵に雷を次々と落とす。", "乌云跟随你，向锁定的敌人接连降下雷电。") },
        { "무적 상태로 조준한 적들 사이를 순간이동하며 벤 뒤 제자리로 돌아옵니다.", L("Invincible, you teleport between targeted enemies slashing them, then return to where you started.", "無敵状態で狙った敵の間を瞬間移動して斬り、元の場所に戻る。", "无敌状态下在锁定的敌人之间瞬移斩击，然后回到原位。") },
        { "플레이어에서 마우스 쪽으로 줄지어 운석이 떨어집니다.", L("Rows of meteors rain down from you toward the mouse.", "プレイヤーからマウスの方へ隕石が列になって落ちる。", "陨石从玩家向鼠标方向成排落下。") },
        { "총알이 적을 1마리 더 관통합니다.", L("Bullets pierce one more enemy.", "弾が敵をもう1体貫通する。", "子弹多穿透1个敌人。") },
        { "적이 코인을 1개 더 떨어뜨립니다.", L("Enemies drop one more coin.", "敵がコインをもう1枚落とす。", "敌人多掉落1枚金币。") },
        { "필살기 게이지가 20% 줄어 필살기를 더 자주 씁니다.", L("Skill gauge is 20% shorter, so you ult more often.", "必殺技ゲージが20%短くなり、必殺技をより頻繁に使える。", "技能槽缩短20%，更频繁地使用必杀技。") },
        { "필살기를 조준하는 동안 타겟이 된 적이 20% 더 느려집니다.", L("Targeted enemies are 20% slower while you aim your ultimate.", "必殺技の照準中、狙われた敵が20%さらに遅くなる。", "瞄准必杀技时，被锁定的敌人额外减速20%。") },
        { "처치 경험치가 10% 늘어납니다.", L("Kill EXP +10%.", "撃破経験値が10%増える。", "击杀经验+10%。") },
        { "주변의 코인을 끌어옵니다. 범위 +4 (최대 4번)", L("Pulls in nearby coins. Range +4 (up to 4 times)", "周りのコインを引き寄せる。範囲+4（最大4回）", "吸引附近的金币。范围+4（最多4次）") },
        { "한 번에 쏘는 총알이 1발 늘지만 한 발당 피해는 줄어듭니다.", L("Fire one more bullet per shot, but each deals less damage.", "一度に撃つ弾が1発増えるが、1発あたりのダメージは減る。", "每次多发射1颗子弹，但单发伤害降低。") },
        { "총알이 적을 밀어내는 힘 +25% (최대 3번)", L("Bullet knockback +25% (up to 3 times)", "弾のノックバック+25%（最大3回）", "子弹击退+25%（最多3次）") },
        { "체력을 모두 회복하고 최대 체력이 12% 늘어납니다.", L("Fully heals and raises max health by 12%.", "体力を全回復し、最大体力が12%増える。", "完全恢复生命，最大生命+12%。") },
        { "받는 피해 -12% (최대 3번)", L("Damage taken -12% (up to 3 times)", "受けるダメージ-12%（最大3回）", "受到伤害-12%（最多3次）") },
        { "시간이 지나면 체력이 회복됩니다. 초당 +0.5 (최대 4번)", L("Regenerate health over time. +0.5 per second (up to 4 times)", "時間とともに体力が回復する。毎秒+0.5（最大4回）", "随时间恢复生命。每秒+0.5（最多4次）") },
        { "적을 처치할 때마다 체력 +1 회복 (최대 3번)", L("Heal +1 health per kill (up to 3 times)", "敵を倒すたびに体力+1回復（最大3回）", "每击杀一个敌人恢复1点生命（最多3次）") },
        { "능력치 상점", L("Stat Shop", "ステータスショップ", "属性商店") },
        { "공격력 · 공격 속도 · 재장전 속도 · 탄창 · 이동 속도를 올립니다. 살수록 값이 오릅니다.", L("Raise attack · fire rate · reload speed · magazine · move speed. Prices rise as you buy.", "攻撃力・攻撃速度・リロード速度・弾倉・移動速度を上げる。買うほど値段が上がる。", "提升攻击力 · 攻击速度 · 装填速度 · 弹匣 · 移动速度。买得越多越贵。") },
        { "2장부터. 특수 무기마다 피해 · 연사 · 탄창 · 고유 특성을 올립니다.", L("From Stage 2. Raise damage · fire rate · magazine · a unique trait for each special weapon.", "第2章から。特殊武器ごとにダメージ・連射・弾倉・固有特性を上げる。", "第2章起。为每把特殊武器提升伤害 · 射速 · 弹匣 · 专属特性。") },
        { "필살기의 위력과 무기마다 다른 특성(타겟 수 · 지속 시간 등)을 올립니다.", L("Raise your ultimate's power and a per-weapon trait (targets · duration, etc.).", "必殺技の威力と武器ごとの特性（ターゲット数・持続時間など）を上げる。", "提升必杀技威力和各武器的特性（目标数 · 持续时间等）。") },
        { "특수 능력 포인트", L("Special Ability Points", "特殊能力ポイント", "特殊能力点") },
        { "중간 보스를 잡으면 얻습니다. T를 눌러 새 능력을 배우거나 가진 능력을 진화합니다.", L("Earned from mid-bosses. Press T to learn a new ability or evolve one you own.", "中ボスを倒すと手に入る。Tで新しい能力を覚えるか、持っている能力を進化させる。", "击败精英首领获得。按T学习新能力或进化已有能力。") },
        { "처음부터 가진 무기", L("Your starting weapon", "最初から持っている武器", "初始武器") },
        { "좌클릭으로 사격, R로 재장전.", L("Left-click to shoot, R to reload.", "左クリックで射撃、Rでリロード。", "左键射击，R键装填。") },
        { "우클릭을 누른 채 적을 조준하고, 떼면 조준한 적들에게 한꺼번에 쏩니다.", L("Hold right-click to target enemies, release to fire at all of them at once.", "右クリックを押したまま敵を狙い、離すと狙った敵に一斉に撃つ。", "按住右键锁定敌人，松开后向所有锁定的敌人齐射。") },
        { "특수 무기", L("Special Weapon", "特殊武器", "特殊武器") },
        { "강화 특성", L("Upgrade Trait", "強化特性", "强化特性") },
        { "즉발", L("Instant", "即発", "瞬发") },
        { "조준", L("Aimed", "照準", "瞄准") },
        { "체력", L("HP", "体力", "生命") },
        { "속도", L("Speed", "速度", "速度") },
        { "접촉 피해", L("Contact Dmg", "接触ダメージ", "接触伤害") },
        // v3.1 캐릭터 이야기 · 검사 베기 · 도적 출혈 돌진
        { "떠돌이 기사는 녹슨 장검 한 자루를 등에 메고 무너진 신전 앞에 섰다.", L("The wandering knight stood before the ruined temple, a rusty longsword on his back.", "流浪の騎士は錆びた長剣を背負い、崩れた神殿の前に立った。", "流浪骑士背着一把生锈的长剑，站在了倒塌的神殿前。") },
        { "총알은 떨어져도, 칼날은 떨어지지 않는다.", L("Bullets run out. A blade never does.", "弾は尽きても、刃は尽きない。", "子弹会打光，剑刃却不会。") },
        { "기사는 망설임 없이 어둠 속으로 뛰어내렸다.", L("Without hesitation, the knight leapt into the dark.", "騎士はためらうことなく闇の中へ飛び降りた。", "骑士毫不犹豫地跳入了黑暗之中。") },
        { "그림자 칼날이라 불리는 도적은 신전 지하에 잠든 보물 이야기를 들었다.", L("The rogue called the Shadow Blade had heard of treasure sleeping beneath the temple.", "影の刃と呼ばれる盗賊は、神殿の地下に眠る宝の噂を聞いた。", "人称暗影之刃的盗贼，听说了沉睡在神殿地下的宝藏。") },
        { "망자든 악마든, 등을 보인 놈부터 쓰러진다.", L("Undead or demon, whoever turns their back falls first.", "亡者でも悪魔でも、背中を見せた奴から倒れる。", "无论亡者还是恶魔，先露出后背的先倒下。") },
        { "도적은 소리 없이 구멍 아래로 몸을 날렸다.", L("Without a sound, the rogue dropped into the hole.", "盗賊は音もなく穴の底へ身を躍らせた。", "盗贼悄无声息地跃入了洞中。") },
        { "숲의 사냥꾼은 죽은 짐승들이 숲을 떠나 신전으로 향하는 것을 보았다.", L("The forest hunter watched dead beasts leave the woods and head for the temple.", "森の狩人は、死んだ獣たちが森を離れ神殿へ向かうのを見た。", "森林猎人看见死去的野兽离开森林，走向神殿。") },
        { "흔적을 따라가자, 무너진 신전의 구멍이 나타났다.", L("Following the tracks, the hunter found a hole in the ruined temple.", "足跡を追うと、崩れた神殿の穴が現れた。", "循着踪迹，倒塌神殿的洞口出现在眼前。") },
        { "화살통은 가득하다. 이번 사냥감은 리치 왕이다.", L("The quiver is full. Today's quarry is the Lich King.", "矢筒は満杯だ。今回の獲物はリッチ王だ。", "箭筒已满。这次的猎物是巫妖王。") },
        { "미친 학자는 오히려 기뻤다. 되살아난 시체라니, 이렇게 좋은 재료가 또 있을까.", L("The mad scholar was delighted. Walking corpses — what finer ingredients could there be?", "狂った学者はむしろ喜んだ。蘇った屍なんて、これ以上の素材があるだろうか。", "疯狂学者反而很高兴。复活的尸体——还有比这更好的材料吗？") },
        { "플라스크를 허리춤에 가득 채우고, 학자는 신전의 구멍으로 뛰어들었다.", L("Belt packed with flasks, the scholar jumped into the temple's hole.", "腰にフラスコを詰め込み、学者は神殿の穴へ飛び込んだ。", "腰间挂满烧瓶，学者跳进了神殿的洞口。") },
        { "“자, 실험을 시작하지.”", L("\"Now then, let the experiment begin.\"", "「さて、実験を始めよう。」", "“那么，实验开始吧。”") },
        { "기사는 이 빠진 장검을 닦아 칼집에 꽂았다.", L("The knight wiped the notched longsword and sheathed it.", "騎士は刃こぼれした長剣を拭い、鞘に収めた。", "骑士擦净了满是缺口的长剑，收入鞘中。") },
        { "사람들은 총 한 자루 없이 세상을 구한 기사를 신기한 듯 바라보았다.", L("People stared in wonder at the knight who saved the world without a single gun.", "人々は銃ひとつ持たずに世界を救った騎士を不思議そうに見つめた。", "人们惊奇地望着这位没用一把枪就拯救了世界的骑士。") },
        { "“총이 아니어도 괜찮다. 지킬 수만 있다면.”", L("\"It needn't be a gun. So long as I can protect them.\"", "「銃でなくてもいい。守れさえすれば。」", "“不是枪也无妨。只要能守护就好。”") },
        { "도적은 리치 왕의 왕관을 슬쩍 품에 넣었다.", L("The rogue quietly slipped the Lich King's crown inside their coat.", "盗賊はリッチ王の王冠をこっそり懐に入れた。", "盗贼悄悄把巫妖王的王冠揣进了怀里。") },
        { "영웅의 이름을 물었을 때, 도적은 이미 그림자 속으로 사라진 뒤였다.", L("When people asked the hero's name, the rogue had already vanished into the shadows.", "英雄の名を尋ねたとき、盗賊はすでに影の中へ消えていた。", "当人们询问英雄的名字时，盗贼早已消失在阴影之中。") },
        { "다음 날, 왕궁의 보물 창고가 텅 비었다는 소문이 돌았다.", L("The next day, rumors spread that the royal treasury was empty.", "翌日、王宮の宝物庫が空っぽになったという噂が流れた。", "第二天，传出了王宫宝库被洗劫一空的传闻。") },
        { "사냥꾼은 마지막 화살을 거두어 화살통에 꽂았다.", L("The hunter gathered the last arrow and slid it back into the quiver.", "狩人は最後の矢を拾い、矢筒に収めた。", "猎人收回最后一支箭，插回箭筒。") },
        { "숲에는 다시 새소리가 돌아왔다.", L("Birdsong returned to the forest.", "森には再び鳥のさえずりが戻ってきた。", "森林里再次响起了鸟鸣。") },
        { "사람들은 숲의 사냥꾼에게 깊이 고개를 숙였다.", L("The people bowed deeply to the forest hunter.", "人々は森の狩人に深く頭を下げた。", "人们向森林猎人深深鞠躬。") },
        { "학자는 킹 슬라임의 점액을 플라스크에 담으며 킬킬 웃었다.", L("The scholar giggled while bottling the King Slime's goo.", "学者はキングスライムの粘液をフラスコに詰めながらクスクス笑った。", "学者一边把史莱姆王的黏液装进烧瓶，一边嘿嘿直笑。") },
        { "“이걸로 논문 세 편은 쓰겠군.”", L("\"That's three papers' worth of material, at least.\"", "「これで論文が三本は書けるな。」", "“这些够我写三篇论文了。”") },
        { "세상은 구해졌다. 대부분은 우연이었지만.", L("The world was saved. Mostly by accident.", "世界は救われた。ほとんどは偶然だったが。", "世界得救了。虽然大部分是出于偶然。") },
        { "파열 화살", L("Bursting Arrow", "破裂の矢", "爆裂箭") },
        { "가득 당긴 화살이 처음 맞힌 적의 자리에서 폭발합니다. (범위 2 · 2.5 · 3칸)", L("A fully drawn arrow explodes where it first hits. (Radius 2 · 2.5 · 3)", "引き絞った矢が最初に当たった敵の位置で爆発します。（範囲2・2.5・3マス）", "满弓之箭在首个命中的敌人处爆炸。（范围2 · 2.5 · 3格）") },
        { "폭발 피해", L("Blast damage", "爆発ダメージ", "爆炸伤害") },
        { "레벨업 스킬", L("Level-up Skills", "レベルアップスキル", "升级技能") },
        { "눌러서 레벨업 스킬 아이콘을 접고 펼칩니다.", L("Click to collapse or expand the level-up skill icons.", "クリックでレベルアップスキルのアイコンを折りたたむ・広げます。", "点击折叠或展开升级技能图标。") },
        { "화염 총구", L("Flame Muzzle", "火炎の銃口", "火焰枪口") },
        { "지옥불 총구", L("Hellfire Muzzle", "業火の銃口", "狱火枪口") },
        { "영혼 탄두", L("Soul Warhead", "魂の弾頭", "灵魂弹头") },
        { "레일 탄두", L("Rail Warhead", "レール弾頭", "轨道弹头") },
        { "쌍발 총구", L("Twin Muzzle", "双発の銃口", "双发枪口") },
        { "심판의 삼연발", L("Judgment Triple Shot", "審判の三連射", "审判三连发") },
        { "작열탄", L("Blazing Rounds", "灼熱弾", "灼热弹") },
        { "산탄 총구", L("Scatter Muzzle", "散弾の銃口", "散弹枪口") },
        { "추적 영혼탄", L("Seeking Soul Rounds", "追尾魂弾", "追踪灵魂弹") },
        { "뇌전 탄환", L("Thunder Rounds", "雷電弾", "雷电弹") },
        { "사신의 탄환", L("Reaper Rounds", "死神の弾丸", "死神子弹") },
        { "총알이 맞힌 적을 3초 동안 불태웁니다. (초당 공격력 35%)", L("Bullets set enemies on fire for 3s. (35% attack per second)", "弾が当たった敵を3秒間燃やします。（毎秒攻撃力35%）", "子弹命中的敌人燃烧3秒。（每秒攻击力35%）") },
        { "불길이 더 세지고 (초당 공격력 60%) 맞은 적 주변으로 번집니다.", L("Fire burns hotter (60% attack per second) and spreads to nearby enemies.", "炎が強まり（毎秒攻撃力60%）、当たった敵の周りへ燃え広がります。", "火焰更猛烈（每秒攻击力60%），并蔓延到周围敌人。") },
        { "총알이 적 둘을 더 꿰뚫고 50% 빠르게 날아가며, 15% 확률로 치명타가 됩니다.", L("Bullets pierce 2 more enemies, fly 50% faster and have a 15% crit chance.", "弾が敵をさらに2体貫通し、50%速く飛び、15%の確率でクリティカルになります。", "子弹额外穿透2个敌人，飞行速度+50%，15%几率暴击。") },
        { "총알이 모든 적을 꿰뚫고 치명타 확률이 30%가 됩니다.", L("Bullets pierce every enemy and crit chance becomes 30%.", "弾がすべての敵を貫通し、クリティカル率が30%になります。", "子弹穿透所有敌人，暴击率变为30%。") },
        { "쏠 때마다 총알 한 발이 더 나갑니다. (피해 60%)", L("Each shot fires one extra bullet. (60% damage)", "撃つたびに弾がもう1発出ます。（ダメージ60%）", "每次射击额外射出1发子弹。（伤害60%）") },
        { "쏠 때마다 총알 두 발이 더 나갑니다. (피해 60%)", L("Each shot fires two extra bullets. (60% damage)", "撃つたびに弾がもう2発出ます。（ダメージ60%）", "每次射击额外射出2发子弹。（伤害60%）") },
        { "총알이 처음 맞힌 자리에서 작게 폭발합니다. (범위 2칸, 피해 70%)", L("Bullets explode where they first hit. (Radius 2, 70% damage)", "弾が最初に当たった場所で小さく爆発します。（範囲2マス、ダメージ70%）", "子弹在首次命中处小范围爆炸。（范围2格，伤害70%）") },
        { "쏠 때마다 짧게 날아가는 산탄 네 발이 함께 퍼집니다. (발당 피해 55%)", L("Each shot also sprays 4 short-range pellets. (55% damage each)", "撃つたびに短く飛ぶ散弾4発が一緒に広がります。（1発ダメージ55%）", "每次射击同时散射4发短程霰弹。（每发伤害55%）") },
        { "총알이 가까운 적을 강하게 쫓아갑니다.", L("Bullets strongly home in on nearby enemies.", "弾が近くの敵を強く追いかけます。", "子弹强力追踪附近敌人。") },
        { "총알이 맞힌 적에게서 35% 확률로 번개가 적 둘에게 튑니다. (피해 50%)", L("Hits have a 35% chance to chain lightning to 2 enemies. (50% damage)", "弾が当たった敵から35%の確率で稲妻が敵2体に跳ねます。（ダメージ50%）", "子弹命中时35%几率闪电弹射到2个敌人。（伤害50%）") },
        { "적을 처치하면 35% 확률로 영혼 낫이 휘돌아 주변을 벱니다. (공격력 180%)", L("Kills have a 35% chance to spin a soul scythe that slashes nearby enemies. (180% attack)", "敵を倒すと35%の確率で魂の鎌が回転して周りを斬ります。（攻撃力180%）", "击杀敌人时35%几率召唤灵魂镰刀旋斩周围。（攻击力180%）") },
        { "마우스 쪽으로 거대한 부채꼴 폭발 3연발", L("Three huge cone blasts toward the mouse", "マウス方向へ巨大な扇形の爆発を3連発", "朝鼠标方向连续3次巨大扇形爆炸") },
        { "화면을 가로지르는 굵은 광선 (광선 위의 적이 많을수록 강함)", L("A thick beam across the screen (stronger with more enemies on it)", "画面を横切る太い光線（光線上の敵が多いほど強い）", "横贯屏幕的粗光束（光束上敌人越多越强）") },
        { "1.6초 동안 사방으로 총알을 난사", L("Spray bullets in all directions for 1.6s", "1.6秒間四方へ弾を乱射", "1.6秒内向四周扫射子弹") },
        { "1.6초 동안 주위 18칸까지 사방으로 총알을 난사", L("Spray bullets in all directions up to 18 tiles around you for 1.6s", "1.6秒間、周囲18マスまで四方へ弾を乱射", "1.6秒内向周围18格内四面扫射子弹") },
        { "폭풍 사거리", L("Storm Range", "嵐の射程", "风暴射程") },
        { "폭풍 사거리 II", L("Storm Range II", "嵐の射程 II", "风暴射程 II") },
        { "총알 폭풍 사거리 +3칸", L("Bullet Storm range +3 tiles", "弾の嵐の射程 +3マス", "子弹风暴射程 +3格") },
        { "마우스 위치에 적을 빨아들이며 태우는 불기둥", L("A fire pillar at the mouse that pulls in and burns enemies", "マウス位置に敵を吸い込みながら燃やす火柱", "在鼠标位置生成吸入并焚烧敌人的火柱") },
        { "영혼 구슬 다섯이 조준한 적에게 번갈아 달려듦", L("Five soul orbs take turns charging the targeted enemies", "魂の玉5つが狙った敵へ交互に突撃", "五颗灵魂珠轮流冲向瞄准的敌人") },
        { "조준한 적들에게 하늘에서 번개가 연달아 떨어짐", L("Lightning strikes the targeted enemies again and again", "狙った敵たちに空から稲妻が連続で落ちる", "闪电从天而降连续劈向瞄准的敌人") },
        { "무적 상태로 조준한 적들 사이를 순간이동하며 벰", L("Teleport between targeted enemies while invincible, slashing each", "無敵状態で狙った敵の間を瞬間移動しながら斬る", "无敌状态下在瞄准的敌人之间瞬移斩击") },
        { "마우스 쪽으로 줄지어 운석이 떨어짐", L("Rows of meteors fall toward the mouse", "マウス方向へ列をなして隕石が落ちる", "陨石成排朝鼠标方向落下") },
        { "능력 효과 +25%", L("Ability effect +25%", "能力効果+25%", "能力效果+25%") },
        { " 능력도 그대로", L(" ability is kept", "の能力もそのまま", "能力保持不变") },
        { "대지의 일격", L("Earth Strike", "大地の一撃", "大地一击") },
        { "채찍 칼날", L("Whip Blade", "鞭の刃", "鞭刃") },
        { "창날 찌르기", L("Spear Thrust", "槍刃突き", "枪刃突刺") },
        { "독 표창", L("Venom Stars", "毒手裏剣", "毒飞镖") },
        { "도박 표창", L("Gambler's Stars", "博打手裏剣", "赌徒飞镖") },
        { "와이어 표창", L("Wire Stars", "ワイヤー手裏剣", "钢丝飞镖") },
        { "그물 화살", L("Net Arrows", "網の矢", "网箭") },
        { "투창 화살", L("Javelin Arrows", "投槍の矢", "投枪箭") },
        { "연사 화살", L("Rapid Arrows", "連射の矢", "连射箭") },
        { "수은 플라스크", L("Quicksilver Flask", "水銀フラスコ", "水银烧瓶") },
        { "자석 플라스크", L("Magnet Flask", "磁石フラスコ", "磁石烧瓶") },
        { "폭죽 플라스크", L("Firework Flask", "花火フラスコ", "烟花烧瓶") },
        { "세 번 벨 때마다 땅을 내리찍어 주변 적에게 피해(150%)를 주고 잠깐 기절시킵니다.", L("Every third swing slams the ground, damaging (150%) and briefly stunning nearby enemies.", "3回斬るごとに地面を叩きつけ、周りの敵にダメージ（150%）を与えて少し気絶させます。", "每挥砍3次就重击地面，对周围敌人造成伤害（150%）并短暂眩晕。") },
        { "베기 사거리 +30%, 칼끝에 맞은 적은 피해 1.5배.", L("Slash range +30%, enemies hit by the tip take 1.5x damage.", "斬撃射程+30%、刃先に当たった敵はダメージ1.5倍。", "挥砍范围+30%，被剑尖击中的敌人受到1.5倍伤害。") },
        { "벨 때마다 앞으로 적을 꿰뚫는 창날이 날아갑니다. (피해 80%)", L("Each swing launches a piercing spear blade forward. (80% damage)", "斬るたびに前へ敵を貫く槍の刃が飛びます。（ダメージ80%）", "每次挥砍向前射出贯穿敌人的枪刃。（伤害80%）") },
        { "표창이 맞은 적에게 독을 쌓고 (최대 5중첩), 공격 속도 +20%.", L("Stars stack poison on hit (up to 5), attack speed +20%.", "手裏剣が当たった敵に毒を重ね（最大5重）、攻撃速度+20%。", "飞镖命中叠加毒素（最多5层），攻击速度+20%。") },
        { "표창 피해가 제각각 (50~170%), 가끔 조커가 폭발합니다.", L("Star damage varies (50~170%), and jokers sometimes explode.", "手裏剣のダメージがバラバラ（50～170%）、時々ジョーカーが爆発します。", "飞镖伤害随机（50~170%），偶尔小丑牌会爆炸。") },
        { "표창이 맞은 적에게서 가까운 적 둘에게 줄이 튀어 벱니다. (피해 50%)", L("Wires leap from the hit enemy to 2 nearby enemies. (50% damage)", "手裏剣が当たった敵から近くの敵2体へワイヤーが跳ねて斬ります。（ダメージ50%）", "钢丝从被命中的敌人弹向附近2个敌人斩击。（伤害50%）") },
        { "반 이상 당긴 화살이 맞은 자리에 그물을 펼쳐 주변 적을 잠깐 묶습니다.", L("Arrows drawn halfway or more cast a net that briefly binds nearby enemies.", "半分以上引いた矢が当たった場所に網を広げ、周りの敵を少し縛ります。", "拉满一半以上的箭在命中处张网，短暂束缚周围敌人。") },
        { "가득 당긴 화살이 모든 적을 꿰뚫고 멀리 날아갈수록 피해가 증가합니다. (최대 200%)", L("Fully drawn arrows pierce every enemy and grow stronger the farther they fly. (up to 200%)", "引き絞った矢がすべての敵を貫き、遠くへ飛ぶほど強くなります。（最大200%）", "满弓之箭穿透所有敌人，飞得越远越强。（最多200%）") },
        { "쏠 때마다 뒤따르는 화살 한 발이 더 나갑니다. (피해 50%)", L("Each shot is followed by one extra arrow. (50% damage)", "撃つたびに後を追う矢がもう1発出ます。（ダメージ50%）", "每次射击额外跟随1支箭。（伤害50%）") },
        { "플라스크가 터진 뒤 가까운 적에게 한 번 더 튕겨 터집니다. (피해 70%)", L("After bursting, the flask bounces to a nearby enemy and bursts again. (70% damage)", "フラスコが割れた後、近くの敵へもう一度跳ねて割れます。（ダメージ70%）", "烧瓶爆裂后再弹向附近敌人爆裂一次。（伤害70%）") },
        { "플라스크가 터지기 전에 주변 적을 끌어모읍니다.", L("The flask pulls nearby enemies in before bursting.", "フラスコが割れる前に周りの敵を引き寄せます。", "烧瓶爆裂前把周围敌人吸过来。") },
        { "플라스크가 터지면 불꽃 세 갈래가 퍼져 한 번씩 더 터집니다. (피해 45%)", L("When the flask bursts, three sparks spread out and burst again. (45% damage)", "フラスコが割れると火花が3方向へ広がり、もう一度ずつ弾けます。（ダメージ45%）", "烧瓶爆裂时三道火花散开各再爆一次。（伤害45%）") },
        { "모든 공격 피해 +12%", L("All attack damage +12%", "全攻撃ダメージ+12%", "所有攻击伤害+12%") },
        { "전리품", L("Trophy", "戦利品", "战利品") },
        { "최대 체력 +15% · 체력 30% 회복", L("Max HP +15% · Heal 30% HP", "最大体力+15%・体力30%回復", "最大生命+15% · 恢复30%生命") },
        { "점착탄", L("Sticky Rounds", "粘着弾", "粘着弹") },
        { "영혼 사냥", L("Soul Hunt", "魂狩り", "灵魂狩猎") },
        { "번개 그물", L("Lightning Net", "雷の網", "闪电之网") },
        { "쏠 때마다 총구에서 짧은 불길이 뿜어져 앞쪽 적을 태웁니다. (사거리 5칸, 피해 45%)", L("Each shot also blasts a short flame from the muzzle, burning enemies in front. (Range 5, 45% damage)", "撃つたびに銃口から短い炎が噴き出し、前方の敵を焼きます。（射程5マス、ダメージ45%）", "每次射击枪口喷出短促火焰，灼烧前方敌人。（射程5格，伤害45%）") },
        { "불길이 더 길고 넓어지며 (사거리 6.5칸, 피해 65%) 맞은 적이 불탑니다.", L("The flame grows longer and wider (Range 6.5, 65% damage) and sets enemies on fire.", "炎がより長く広くなり（射程6.5マス、ダメージ65%）、当たった敵が燃えます。", "火焰更长更宽（射程6.5格，伤害65%），命中的敌人会燃烧。") },
        { "사격을 잠깐 멈췄다 쏘면 첫 발이 충전탄이 되어 모든 적을 꿰뚫고 피해 300%.", L("After a short pause in firing, your first shot is charged: it pierces every enemy and deals 300% damage.", "射撃を少し止めてから撃つと、最初の1発がチャージ弾になり全ての敵を貫通しダメージ300%。", "短暂停火后射出的第一发成为充能弹，穿透所有敌人并造成300%伤害。") },
        { "충전이 더 빨리 되고, 충전탄 피해 450%.", L("Charges faster, and charged shots deal 450% damage.", "チャージが速くなり、チャージ弾のダメージ450%。", "充能更快，充能弹伤害450%。") },
        { "총알에 맞은 적에게 폭탄이 붙어 1.5초 뒤 터집니다. (범위 2.5칸, 피해 110%)", L("Hit enemies get a bomb stuck to them that explodes after 1.5s. (Radius 2.5, 110% damage)", "弾が当たった敵に爆弾がくっつき、1.5秒後に爆発します。（範囲2.5マス、ダメージ110%）", "被子弹命中的敌人身上粘上炸弹，1.5秒后爆炸。（范围2.5格，伤害110%）") },
        { "적을 처치하면 영혼탄 세 발이 튀어나와 가까운 적을 쫓아갑니다. (피해 60%)", L("Kills release three soul shots that chase nearby enemies. (60% damage)", "敵を倒すと魂弾3発が飛び出し、近くの敵を追いかけます。（ダメージ60%）", "击杀敌人时射出三发灵魂弹追踪附近敌人。（伤害60%）") },
        { "총알이 맞힌 적과 바로 전에 맞힌 적 사이에 2초 동안 번개 줄이 이어져, 줄에 닿는 적이 계속 감전됩니다. (0.3초마다 공격력 30%, 줄 최대 4개)", L("Each hit links the enemy you just hit to the one before with a lightning line for 2s, shocking every enemy it touches. (30% attack every 0.3s, up to 4 lines)", "弾が当たった敵と直前に当てた敵の間に2秒間、雷の線がつながり、線に触れた敵を感電させ続ける。(0.3秒ごとに攻撃力30%、線は最大4本)", "子弹命中的敌人与上一个命中的敌人之间会连起持续2秒的闪电线，持续电击碰到线的敌人。(每0.3秒攻击力30%，最多4条)") },
        { "기사의 기세", L("Knight's Momentum", "騎士の勢い", "骑士气势") },
        { "와이어 덫", L("Wire Snare", "ワイヤーの罠", "钢丝陷阱") },
        { "속사 화살", L("Quickdraw Arrows", "速射の矢", "速射箭") },
        { "움직이면서 베면 피해 +40%.", L("Slashing while moving deals +40% damage.", "移動しながら斬るとダメージ+40%。", "移动中挥砍伤害+40%。") },
        { "표창에 맞은 적과 가까운 적 하나가 줄로 묶여 1초 동안 70% 느려집니다.", L("The hit enemy and one nearby enemy are tied together and slowed by 70% for 1s.", "手裏剣が当たった敵と近くの敵1体がワイヤーで縛られ、1秒間70%遅くなります。", "被飞镖命中的敌人与附近一个敌人被钢丝绑住，1秒内减速70%。") },
        { "시위를 25% 더 빨리 당기고, 반 이상 당긴 화살은 적을 하나 더 꿰뚫습니다.", L("Draw 25% faster, and arrows drawn halfway or more pierce one more enemy.", "弦を25%速く引き、半分以上引いた矢は敵をもう1体貫通します。", "拉弓速度+25%，拉满一半以上的箭额外穿透1个敌人。") },
        { "가득 당긴 화살에 맞은 적이 크게 밀려나고 잠깐 기절합니다.", L("Enemies hit by a fully drawn arrow are knocked far back and briefly stunned.", "引き絞った矢に当たった敵が大きく吹き飛ばされ、少し気絶します。", "被满弓之箭命中的敌人被大幅击退并短暂眩晕。") },
        { "기절 시간", L("Stun time", "気絶時間", "眩晕时间") },
        { "강풍 화살", L("Gust Arrow", "強風の矢", "强风箭") },
        { "치명타 확률", L("Crit Chance", "クリティカル率", "暴击率") },
        { "치명타 피해", L("Crit Damage", "クリティカルダメージ", "暴击伤害") },
