        { "떠돌이 상점", L("Wandering Shop", "さすらいの商店", "流浪商店") },
        { "코인으로 능력을 영구히 올리고, 물약으로 잠시 힘을 빌립니다", L("Spend coins on permanent upgrades, or borrow power for a while with potions", "コインで能力を永続強化し、ポーションで一時的に力を借りる", "用金币永久提升能力，或用药水暂时借取力量") },
        { "닫기 [P]", L("Close [P]", "閉じる [P]", "关闭 [P]") },
        { "회복 물약", L("Healing Potion", "回復ポーション", "治疗药水") },
        { "축소 물약", L("Shrinking Potion", "縮小ポーション", "缩小药水") },
