        { "질풍 물약", L("Gale Potion", "疾風ポーション", "疾风药水") },
        { "체력 40% 회복", L("Restore 40% HP", "体力40%回復", "恢复40%生命") },
        { "45초 동안 몸이 작아져 덜 맞음", L("Shrink for 45s and get hit less", "45秒間体が小さくなり当たりにくい", "45秒内身体缩小，更不易被击中") },
        { "45초 동안 공격 속도 +30%", L("+30% attack speed for 45s", "45秒間 攻撃速度+30%", "45秒内攻击速度+30%") },
        { "45초 동안 이동 속도 +25%", L("+25% move speed for 45s", "45秒間 移動速度+25%", "45秒内移动速度+25%") },
        { "체력 가득", L("HP full", "体力満タン", "生命已满") },
        { "그림자 숙련", L("Shadow Mastery", "影の熟練", "暗影精通") },
        { "돌진 뒤 2초 동안 이동 속도 +35%", L("+35% move speed for 2s after dashing", "突進後2秒間 移動速度+35%", "突进后2秒内移动速度+35%") },
        { "돌진이 끝난 자리 주변의 적을 1.5초 동안 60% 느리게", L("Slows enemies around the landing spot by 60% for 1.5s", "突進の着地点周辺の敵を1.5秒間60%鈍化", "使突进落点周围的敌人减速60%，持续1.5秒") },
        { "돌진 거리 +30% · 돌진 뒤 무적 시간 두 배", L("+30% dash distance · Double invincibility after dashing", "突進距離+30%・突進後の無敵時間2倍", "突进距离+30% · 突进后无敌时间翻倍") },
        { "돌진 뒤 3초 안에 우클릭으로 한 번 더 돌진 (게이지 없이)", L("Right-click within 3s after a dash to dash again (no gauge)", "突進後3秒以内に右クリックでもう一度突進（ゲージ不要）", "突进后3秒内右键可再突进一次（无需能量）") },
        { "돌진으로 벤 적 하나당 필살기 게이지 4% 되돌려 받음 (최대 40%)", L("Refund 4% ultimate gauge per enemy cut by the dash (max 40%)", "突進で斬った敵1体ごとに必殺技ゲージ4%回復（最大40%）", "突进每斩中一个敌人返还4%必杀技能量（最多40%）") },
        { "약하지만 빠른 표창 세례와 그림자 돌진으로 싸우는 암살자.", L("A frail assassin who fights with a hail of fast throwing stars and shadow dashes.", "非力だが素早い手裏剣の雨と影の突進で戦う暗殺者。", "虽然柔弱，却以飞快的飞镖和暗影突进作战的刺客。") },
        { "출혈 돌진", L("Bleeding Dash", "出血突進", "出血突进") },
        { "무적 상태로 마우스 방향으로 돌진해, 지나간 적에게 출혈 피해를 입힙니다 (즉발). 영혼 트리에서 그림자 숙련을 배우면 돌진에 이동 속도 · 둔화 · 연속 돌진 등이 붙습니다", L("Dash toward the mouse while invincible, making every enemy you pass bleed (instant). Learning Shadow Mastery in the Soul Tree adds speed, slows, chained dashes and more to the dash", "無敵状態でマウスの方向へ突進し、通り過ぎた敵に出血ダメージを与えます（即発動）。魂のツリーで影の熟練を覚えると突進に移動速度・鈍化・連続突進などが付きます", "在无敌状态下朝鼠标方向突进，使途经的敌人流血（瞬发）。在灵魂树学习暗影精通后，突进会附带移速 · 减速 · 连续突进等效果") },
        { "높을수록 늦게 참", L("Higher = fills slower", "高いほど遅く溜まる", "越高积累越慢") },
        // 1.7.3 레벨업 쌓기
        { "능력 고르기", L("Choose ability", "能力を選ぶ", "选择能力") },
        { "레벨업!", L("Level Up!", "レベルアップ！", "升级！") },
        { "레벨이 오르면 능력 포인트가 쌓입니다. [{INTERACT}]를 눌러 원할 때 능력을 고르세요.", L("Leveling up stores ability points. Press [{INTERACT}] whenever you want to choose.", "レベルが上がると能力ポイントが貯まります。好きな時に[{INTERACT}]で選びましょう。", "升级会积攒能力点，随时按 [{INTERACT}] 选择能力。") },
        // 1.7.2 검사 근접 특성 · 설정 · 도움말 · 결과
        { "검을 크게 휘둘러 앞쪽 부채꼴의 적을 직접 벱니다. 근접 특성: 휘두르는 동안 받는 피해 절반 · 벤 적을 크게 밀쳐냄 · 벤 만큼 조금 회복", L("Swings the longsword in a wide arc, cutting enemies directly. Melee traits: half damage taken while swinging · knocks cut enemies far back · heals a little per hit", "長剣を大きく振り、前方の敵を直接斬ります。近接特性: 振っている間は被ダメージ半減 · 斬った敵を大きく押し返す · 斬った分だけ少し回復", "大幅挥舞长剑直接斩击前方敌人。近战特性：挥砍时受到伤害减半 · 大幅击退被斩敌人 · 按斩中数量少量回复") },
        { "평타로 벤 적 하나당 회복량이 늘어납니다. (한 번에 최대 3마리)", L("Increases healing per enemy your swing hits. (up to 3 per swing)", "通常攻撃で斬った敵1体ごとの回復量が増えます。(1回につき最大3体)", "提高普攻每命中一个敌人的回复量。（每次最多3个）") },
        { "게임", L("Gameplay", "ゲーム", "游戏") },
        { "도움말 안내", L("Tips", "ヒント表示", "提示") },
        { "피해 숫자", L("Damage numbers", "ダメージ数値", "伤害数字") },
        { "내 이펙트 투명도", L("My effects opacity", "自分のエフェクト不透明度", "我的特效不透明度") },
        { "크게", L("Large", "大きく", "放大") },
        { "끄기", L("Off", "オフ", "关闭") },
        { "색각 이상 모드", L("Color-blind mode", "色覚サポート", "色盲模式") },
        { "키 아이콘", L("Key icons", "キーアイコン", "按键图标") },
        { "도움말", L("Tip", "ヒント", "提示") },
        { "{MOVE}로 이동, 마우스로 조준, 좌클릭으로 공격합니다.", L("Move with {MOVE}, aim with the mouse, left-click to attack.", "{MOVE}で移動、マウスで狙い、左クリックで攻撃します。", "{MOVE} 移动，鼠标瞄准，左键攻击。") },
        { "특수 능력 포인트는 [{UPGRADE}]를 눌러 새 능력을 배우거나 가진 능력을 진화하는 데 씁니다.", L("Press [{UPGRADE}] to spend special points on new abilities or to evolve ones you have.", "[{UPGRADE}]で特殊能力ポイントを使い、新しい能力を覚えたり進化させたりします。", "按 [{UPGRADE}] 使用特殊能力点学习新能力或进化已有能力。") },
        { "필살기 게이지가 가득 찼습니다! 우클릭으로 필살기를 씁니다.", L("Your ultimate gauge is full! Right-click to use your ultimate.", "必殺技ゲージが満タンです！右クリックで必殺技を使います。", "技能槽已满！右键释放必杀技。") },
        { "[{SWAP}]로 특수 무기와 기본 무기를 바꿔 듭니다. [{RELOAD}]는 장전입니다.", L("Press [{SWAP}] to switch between special and basic weapons. [{RELOAD}] reloads.", "[{SWAP}]で特殊武器と基本武器を持ち替えます。[{RELOAD}]でリロード。", "按 [{SWAP}] 切换特殊武器和基础武器，[{RELOAD}] 装填。") },
        { "스킬은 [{SKILL1}] · [{SKILL2}] · [{SKILL3}]로 씁니다. 쿨타임은 왼쪽 아래 칸에 보입니다.", L("Use skills with [{SKILL1}] · [{SKILL2}] · [{SKILL3}]. Cooldowns show in the bottom-left tiles.", "スキルは[{SKILL1}] · [{SKILL2}] · [{SKILL3}]で使います。クールタイムは左下に表示されます。", "技能用 [{SKILL1}] · [{SKILL2}] · [{SKILL3}] 释放，冷却显示在左下角。") },
        { "떠돌이 상점에서는 코인으로 공격력 · 체력 등을 영구히 올릴 수 있습니다. 가까이 가서 [{INTERACT}]", L("At the wandering shop you can spend coins on permanent attack, health and more. Walk up and press [{INTERACT}]", "さすらいのショップではコインで攻撃力・体力などを永続的に上げられます。近づいて[{INTERACT}]", "在流浪商店可用金币永久提升攻击力、生命等。靠近后按 [{INTERACT}]") },
        { "플레이 시간 ", L("Time ", "プレイ時間 ", "游戏时间 ") },
