        // v3.5 캐릭터 특수 능력 (검사 · 도적 · 궁수 · 연금술사)
        { "전쟁 망치", L("War Hammer", "ウォーハンマー", "战锤") },
        { "가까운 땅을 내리찍어 주변 적에게 피해를 주고 잠깐 기절시킵니다. (공격력 200%)\n진화: 범위 증가, 기절 두 배", L("Smash the ground nearby, damaging and briefly stunning enemies. (200% attack)\nEvolved: larger area, double stun", "近くの地面を叩きつけ、周囲の敵にダメージを与えて少し気絶させます。(攻撃力200%)\n進化: 範囲拡大、気絶2倍", "猛砸附近地面，伤害并短暂击晕周围敌人。（攻击力200%）\n进化：范围扩大，击晕翻倍") },
        { "채찍검", L("Whip Sword", "蛇腹剣", "鞭剑") },
        { "길게 휘어지는 칼날 채찍. 끝부분에 맞은 적은 두 배 가까운 피해를 받습니다.\n진화: 더 길고, 끝 피해 증가", L("A long, bending blade whip. Enemies hit by the tip take nearly double damage.\nEvolved: longer, stronger tip", "長くしなる刃の鞭。先端に当たった敵は約2倍のダメージを受けます。\n進化: より長く、先端ダメージ増加", "修长弯曲的刃鞭，鞭梢命中的敌人受到近两倍伤害。\n进化：更长，鞭梢伤害提高") },
        { "기창", L("Knight's Lance", "騎槍", "骑枪") },
        { "창을 앞세워 짧게 돌격하며 지나간 적을 찌르고 밀쳐냅니다. (공격력 140%)\n진화: 더 멀리, 돌격 중 무적", L("Charge a short distance lance-first, piercing and shoving enemies aside. (140% attack)\nEvolved: farther, invincible while charging", "槍を構えて短く突進し、通り道の敵を突いて押しのけます。(攻撃力140%)\n進化: より遠く、突進中無敵", "持枪短距冲锋，刺穿并推开沿途敌人。（攻击力140%）\n进化：更远，冲锋时无敌") },
        { "전투 함성", L("War Cry", "雄叫び", "战吼") },
        { "크게 외쳐 주변 적을 밀쳐내고 6초 동안 공격력이 30% 오릅니다.\n진화: 공격력 +45%", L("Roar to push nearby enemies away and gain +30% attack for 6s.\nEvolved: +45% attack", "雄叫びで周囲の敵を押しのけ、6秒間攻撃力が30%上がります。\n進化: 攻撃力+45%", "怒吼震退周围敌人，6秒内攻击力提高30%。\n进化：攻击力+45%") },
        { "심판의 대검", L("Judgment Blade", "審判の大剣", "审判巨剑") },
        { "마우스 위치에 하늘에서 거대한 검이 떨어져 크게 베고 기절시킵니다. (공격력 640%)\n진화: 대검 세 자루", L("A giant sword falls from the sky at the cursor, cleaving and stunning. (640% attack)\nEvolved: three swords", "マウス位置に空から巨大な剣が落ち、大きく斬って気絶させます。(攻撃力640%)\n進化: 大剣3本", "巨剑从天而降落在鼠标位置，重斩并击晕。（攻击力640%）\n进化：三把巨剑") },
        { "마우스 쪽으로 땅을 길게 갈라 한 줄의 적에게 피해를 주고 느리게 만듭니다. (공격력 240%)\n진화: 세 갈래로 갈라짐", L("Split the earth toward the cursor, damaging and slowing a line of enemies. (240% attack)\nEvolved: splits three ways", "マウス方向に大地を長く裂き、一列の敵にダメージを与えて遅くします。(攻撃力240%)\n進化: 3方向に裂ける", "朝鼠标方向劈开大地，伤害并减速一列敌人。（攻击力240%）\n进化：分裂成三道") },
        { "불굴", L("Unyielding", "不屈", "不屈") },
        { "잃은 체력이 많을수록 공격력이 오릅니다. (최대 +40%)\n진화: 최대 +60%", L("The more health you've lost, the higher your attack. (up to +40%)\nEvolved: up to +60%", "失った体力が多いほど攻撃力が上がります。(最大+40%)\n進化: 最大+60%", "损失的生命越多，攻击力越高。（最多+40%）\n进化：最多+60%") },
        { "전투 열기", L("Battle Fervor", "戦いの熱気", "战斗狂热") },
        { "적을 처치할 때마다 4초 동안 공격 속도 +5% (최대 5중첩).\n진화: +6%, 최대 8중첩", L("Each kill grants +5% attack speed for 4s (up to 5 stacks).\nEvolved: +6%, up to 8 stacks", "敵を倒すたびに4秒間攻撃速度+5%(最大5重)。\n進化: +6%、最大8重", "每次击杀4秒内攻击速度+5%（最多叠5层）。\n进化：+6%，最多8层") },
        { "독침 대롱", L("Blowgun", "吹き矢", "吹箭筒") },
        { "누르고 있으면 독침을 빠르게 붑니다. 맞은 적은 중독이 쌓입니다. (최대 5중첩)\n진화: 최대 10중첩", L("Hold to rapidly blow poison darts. Hits stack poison. (up to 5)\nEvolved: up to 10 stacks", "押し続けると毒針を素早く吹きます。当たった敵に毒が蓄積します。(最大5重)\n進化: 最大10重", "按住快速吹出毒针，命中叠加中毒。（最多5层）\n进化：最多10层") },
        { "도박 카드", L("Trick Cards", "ギャンブルカード", "赌徒卡牌") },
        { "카드 세 장을 던집니다. 카드마다 피해가 제각각이고, 가끔 조커가 터집니다.\n진화: 다섯 장, 조커 확률 두 배", L("Throw three cards with random damage. Sometimes a Joker explodes.\nEvolved: five cards, double Joker chance", "カードを3枚投げます。ダメージはカードごとにばらばらで、たまにジョーカーが爆発します。\n進化: 5枚、ジョーカー確率2倍", "掷出三张伤害随机的卡牌，偶尔会有爆炸的小丑牌。\n进化：五张，小丑牌几率翻倍") },
        { "살상 와이어", L("Razor Wire", "殺傷ワイヤー", "杀伤钢丝") },
        { "클릭한 곳에 와이어 고리를 박습니다. 고리를 잇는 줄에 닿은 적은 계속 베입니다. (고리 3개)\n진화: 고리 5개", L("Click to plant wire anchors. Enemies touching the wires between them keep getting cut. (3 anchors)\nEvolved: 5 anchors", "クリックした場所にワイヤーの杭を打ちます。杭をつなぐ糸に触れた敵は斬られ続けます。(杭3本)\n進化: 杭5本", "在点击处钉下钢丝锚点，碰到锚点间钢丝的敌人会被持续切割。（3个锚点）\n进化：5个锚点") },
        { "죽음의 표식", L("Death Mark", "死の刻印", "死亡印记") },
        { "마우스 근처의 적에게 표식. 3초 뒤 큰 피해로 터집니다. 그 전에 쓰러지면 쿨타임 초기화. (공격력 800%)\n진화: 표식 세 개", L("Mark the enemy near the cursor; it bursts for huge damage after 3s. If it dies first, the cooldown resets. (800% attack)\nEvolved: three marks", "マウス近くの敵に刻印。3秒後に大ダメージで弾けます。先に倒れるとクールタイムがリセット。(攻撃力800%)\n進化: 刻印3つ", "给鼠标附近的敌人打上印记，3秒后爆发巨额伤害；若目标提前倒下则重置冷却。（攻击力800%）\n进化：三个印记") },
        { "마름쇠", L("Caltrops", "撒菱", "铁蒺藜") },
        { "주변에 마름쇠를 흩뿌립니다. 밟은 적은 피해를 입고 느려집니다.\n진화: 마름쇠 두 배", L("Scatter caltrops around you. Enemies that step on them are hurt and slowed.\nEvolved: double caltrops", "周囲に撒菱をばらまきます。踏んだ敵はダメージを受けて遅くなります。\n進化: 撒菱2倍", "在周围撒下铁蒺藜，踩中的敌人受伤并减速。\n进化：铁蒺藜翻倍") },
        { "소매치기", L("Pickpocket", "スリ", "扒窃") },
        { "순식간에 주변 적 6명 사이를 누비며 벱니다. 털린 적은 쓰러질 때 코인을 1개 더 떨어뜨립니다.\n진화: 8명", L("Dart between up to 6 nearby enemies in an instant, cutting each. Robbed enemies drop 1 extra coin when they fall.\nEvolved: 8 enemies", "一瞬で周囲の敵6体の間を駆け抜けて斬ります。盗まれた敵は倒れるとコインを1枚多く落とします。\n進化: 8体", "瞬间穿梭于周围最多6个敌人之间逐一斩击，被扒窃的敌人倒下时多掉落1枚金币。\n进化：8个") },
        { "회피 본능", L("Evasion", "回避本能", "闪避本能") },
        { "받는 공격을 15% 확률로 피합니다.\n진화: 25%", L("15% chance to dodge incoming attacks.\nEvolved: 25%", "受ける攻撃を15%の確率で回避します。\n進化: 25%", "有15%几率闪避受到的攻击。\n进化：25%") },
        { "연쇄 처치", L("Killing Spree", "連続キル", "连杀") },
        { "적을 처치하면 2초 동안 이동 속도 +15%, 모든 스킬 쿨타임 0.3초 감소.\n진화: 쿨타임 0.6초 감소", L("Kills grant +15% move speed for 2s and cut all skill cooldowns by 0.3s.\nEvolved: 0.6s", "敵を倒すと2秒間移動速度+15%、全スキルのクールタイム0.3秒短縮。\n進化: 0.6秒短縮", "击杀后2秒内移动速度+15%，所有技能冷却减少0.3秒。\n进化：减少0.6秒") },
        { "그물 활", L("Net Bow", "網弓", "网弓") },
        { "맞은 자리에 그물이 펼쳐져 주변 적을 묶습니다.\n진화: 그물이 더 넓고 오래", L("A net bursts open where the arrow hits, binding nearby enemies.\nEvolved: wider, longer net", "当たった場所に網が広がり、周囲の敵を縛ります。\n進化: 網がより広く長く", "命中处张开大网，束缚周围敌人。\n进化：网更大更久") },
        { "투창", L("Javelin", "投げ槍", "标枪") },
        { "모든 적을 꿰뚫는 무거운 창. 멀리 날아갈수록 피해가 커집니다. (최대 공격력 240%)\n진화: 최대 400%", L("A heavy javelin that pierces everything. Deals more damage the farther it flies. (up to 240% attack)\nEvolved: up to 400%", "すべての敵を貫く重い槍。遠くへ飛ぶほどダメージが増えます。(最大攻撃力240%)\n進化: 最大400%", "贯穿所有敌人的重标枪，飞得越远伤害越高。（最高攻击力240%）\n进化：最高400%") },
        { "속사 활", L("Burst Bow", "速射弓", "速射弓") },
        { "한 번 누르면 화살 세 발을 눈 깜짝할 새 연달아 쏩니다. (발당 공격력 60%)\n진화: 다섯 발", L("Each click fires three arrows in a lightning-fast burst. (60% attack each)\nEvolved: five arrows", "一度押すと矢を3本、瞬く間に連射します。(1本あたり攻撃力60%)\n進化: 5本", "每次点击瞬间连射三箭。（每箭攻击力60%）\n进化：五箭") },
        { "매의 급습", L("Falcon Dive", "鷹の急襲", "猎鹰突袭") },
        { "사냥 매를 날려 마우스 근처의 적을 차례로 덮칩니다. (적마다 공격력 200%)\n진화: 더 많은 적", L("Send your falcon to swoop on enemies near the cursor one after another. (200% attack each)\nEvolved: more enemies", "狩りの鷹を放ち、マウス近くの敵を次々に襲います。(敵ごとに攻撃力200%)\n進化: より多くの敵", "放出猎鹰依次扑击鼠标附近的敌人。（每个敌人攻击力200%）\n进化：更多敌人") },
        { "돌풍 화살", L("Gale Arrow", "突風の矢", "疾风之箭") },
        { "거센 바람을 두른 거대한 화살. 한 줄을 꿰뚫고 적을 멀리 날려 버립니다. (공격력 240%)\n진화: 화살이 두 배 커짐", L("A giant arrow wrapped in gale winds that pierces a line and blasts enemies away. (240% attack)\nEvolved: arrow twice as big", "強風をまとった巨大な矢。一列を貫き、敵を遠くへ吹き飛ばします。(攻撃力240%)\n進化: 矢が2倍に", "裹挟狂风的巨箭，贯穿一列并把敌人吹飞。（攻击力240%）\n进化：箭矢变为两倍大") },
        { "사냥꾼의 집중", L("Hunter's Focus", "狩人の集中", "猎人专注") },
        { "5초 동안 활시위를 순식간에 가득 당깁니다.\n진화: 8초", L("For 5s, your bow draws to full instantly.\nEvolved: 8s", "5秒間、弓を一瞬で引き絞ります。\n進化: 8秒", "5秒内瞬间拉满弓弦。\n进化：8秒") },
        { "전리품 사냥", L("Trophy Hunter", "戦利品狩り", "战利品猎人") },
        { "적을 처치할 때마다 최대 체력 +0.4 (최대 +30).\n진화: +0.8 (최대 +60)", L("Each kill grants +0.4 max health (up to +30).\nEvolved: +0.8 (up to +60)", "敵を倒すたびに最大体力+0.4(最大+30)。\n進化: +0.8(最大+60)", "每次击杀最大生命+0.4（最多+30）。\n进化：+0.8（最多+60）") },
        { "거리 유지", L("Keep Distance", "間合い", "保持距离") },
        { "5칸 안에 적이 없으면 공격력이 25% 오릅니다.\n진화: +40%", L("+25% attack while no enemy is within 5 tiles.\nEvolved: +40%", "5マス以内に敵がいないと攻撃力が25%上がります。\n進化: +40%", "5格内没有敌人时攻击力提高25%。\n进化：+40%") },
        { "수은 구슬", L("Quicksilver Orb", "水銀玉", "水银珠") },
        { "벽과 적에게 튕겨 다니는 수은 구슬. 네 번 튕기면 터집니다.\n진화: 일곱 번 튕김", L("A quicksilver orb that bounces off walls and enemies, bursting after four bounces.\nEvolved: seven bounces", "壁と敵に跳ね返る水銀の玉。4回跳ねると弾けます。\n進化: 7回跳ねる", "在墙壁与敌人间弹跳的水银珠，弹跳四次后爆裂。\n进化：弹跳七次") },
        { "자석 폭탄", L("Magnet Bomb", "磁石爆弾", "磁力炸弹") },
        { "떨어진 자리로 주변 적을 끌어모은 뒤 폭발합니다. (공격력 180%)\n진화: 더 넓게 끌어당기고 두 번 폭발", L("Pulls nearby enemies to where it lands, then explodes. (180% attack)\nEvolved: wider pull, explodes twice", "落ちた場所に周囲の敵を引き寄せてから爆発します。(攻撃力180%)\n進化: より広く引き寄せ2回爆発", "把周围敌人吸到落点后爆炸。（攻击力180%）\n进化：吸引范围更大，爆炸两次") },
        { "폭죽 발사기", L("Firework Launcher", "花火ランチャー", "烟花发射器") },
        { "마우스 위치로 폭죽을 쏘아 올려 색색의 불꽃으로 터뜨립니다.\n진화: 불꽃 다섯 → 여덟 갈래", L("Launch a firework at the cursor that bursts into colorful sparks.\nEvolved: 5 → 8 bursts", "マウス位置に花火を打ち上げ、色とりどりの火花で弾けさせます。\n進化: 火花5 → 8つ", "向鼠标位置发射烟花，绽放成五彩火花。\n进化：火花五道 → 八道") },
        { "현자의 돌", L("Philosopher's Stone", "賢者の石", "贤者之石") },
        { "6초 동안 던지는 플라스크가 모두 불안정해져 크게 폭발합니다.\n진화: 9초", L("For 6s, every flask you throw is unstable and explodes big.\nEvolved: 9s", "6秒間、投げるフラスコがすべて不安定になり大爆発します。\n進化: 9秒", "6秒内投掷的烧瓶全部变得不稳定并猛烈爆炸。\n进化：9秒") },
        { "시간 역행 물약", L("Rewind Elixir", "時間逆行の薬", "时光倒流药剂") },
        { "3초 전의 자리로 되돌아가고, 그때 체력이 더 많았다면 되찾습니다.\n진화: 쿨타임 감소", L("Return to where you were 3s ago, and regain your health from then if it was higher.\nEvolved: shorter cooldown", "3秒前の場所に戻り、そのとき体力が多ければ取り戻します。\n進化: クールタイム短縮", "回到3秒前的位置，若当时生命更多则一并恢复。\n进化：冷却缩短") },
        { "거대화 물약", L("Giant Potion", "巨大化の薬", "巨大化药剂") },
        { "5초 동안 몸이 커져 받는 피해가 절반, 닿는 적을 밀쳐내며 피해를 줍니다.\n진화: 8초", L("Grow huge for 5s: take half damage and shove and hurt enemies you touch.\nEvolved: 8s", "5秒間体が大きくなり、受けるダメージが半分、触れた敵を押しのけてダメージを与えます。\n進化: 8秒", "5秒内体型变大，受到伤害减半，并推开、伤害接触的敌人。\n进化：8秒") },
        { "연금 순환", L("Alchemic Cycle", "錬金循環", "炼金循环") },
        { "스킬을 쓸 때마다 체력 4% 회복, 다른 스킬 쿨타임 1초 감소.\n진화: 체력 6%, 2초 감소", L("Each skill use heals 4% health and cuts other skill cooldowns by 1s.\nEvolved: 6% health, 2s", "スキルを使うたびに体力4%回復、他のスキルのクールタイム1秒短縮。\n進化: 体力6%、2秒短縮", "每次使用技能恢复4%生命，其他技能冷却减少1秒。\n进化：生命6%，减少2秒") },
        { "불안정 연구", L("Volatile Research", "不安定研究", "不稳定研究") },
        { "불안정한 플라스크가 나올 확률이 15% → 35%, 불안정 폭발이 불을 붙입니다.\n진화: 50%", L("Unstable flask chance 15% → 35%, and unstable blasts set enemies on fire.\nEvolved: 50%", "不安定なフラスコが出る確率が15% → 35%、不安定な爆発が炎上させます。\n進化: 50%", "不稳定烧瓶出现几率15% → 35%，不稳定爆炸会点燃敌人。\n进化：50%") },
        { "대지 진동", L("Earthquake", "大地震動", "大地震荡") },
        { "망치로 땅을 연달아 내리쳐 앞으로 나아가는 충격파 여섯 번을 일으킵니다. (공격력 240%씩, 기절)", L("Pound the ground again and again, sending six shockwaves marching forward. (240% attack each, stun)", "槌で地面を連打し、前へ進む衝撃波を6回起こします。(攻撃力240%ずつ、気絶)", "连续锤击地面，向前推进六道冲击波。（每道攻击力240%，击晕）") },
        { "뱀의 춤", L("Serpent Dance", "蛇の舞", "蛇之舞") },
        { "채찍검을 사방 열두 방향으로 휘몰아칩니다. (공격력 160%씩)", L("Lash the whip sword in twelve directions. (160% attack each)", "蛇腹剣を四方12方向に振り回します。(攻撃力160%ずつ)", "向十二个方向狂舞鞭剑。（每道攻击力160%）") },
        { "기사 돌격", L("Knight's Charge", "騎士突撃", "骑士冲锋") },
        { "무적 상태로 멀리 돌격해 지나간 적을 모두 날려 버립니다. (공격력 560%)", L("Charge far while invincible, sending everything in your path flying. (560% attack)", "無敵状態で遠くまで突撃し、通り道の敵をすべて吹き飛ばします。(攻撃力560%)", "无敌状态下远距离冲锋，撞飞沿途所有敌人。（攻击力560%）") },
        { "독안개", L("Toxic Fog", "毒霧", "毒雾") },
        { "마우스 위치에 5초 동안 독안개를 퍼뜨려 안의 적에게 중독을 계속 쌓습니다.", L("Spread toxic fog at the cursor for 5s, stacking poison on enemies inside.", "マウス位置に5秒間毒霧を広げ、中の敵に毒を蓄積し続けます。", "在鼠标位置散布毒雾5秒，持续为其中敌人叠加中毒。") },
        { "잭팟", L("Jackpot", "ジャックポット", "头奖") },
        { "카드 52장을 소용돌이치듯 사방으로 뿌립니다. 조커도 잔뜩 섞여 있습니다.", L("Spiral 52 cards out in every direction, with plenty of Jokers mixed in.", "カード52枚を渦巻くように四方へばらまきます。ジョーカーもたっぷり。", "螺旋般向四周撒出52张卡牌，其中混着大量小丑牌。") },
        { "거미줄 감옥", L("Web Prison", "蜘蛛の檻", "蛛网牢笼") },
        { "주변을 와이어로 둘러싼 뒤 조여 들어가며 닿는 적을 벱니다.", L("Surround yourself with wire, then tighten it, cutting every enemy it touches.", "周囲をワイヤーで囲み、締め上げながら触れた敵を斬ります。", "用钢丝环绕四周，再收紧切割触及的敌人。") },
        { "대형 그물", L("Great Net", "大網", "巨网") },
        { "마우스 위치에 거대한 그물을 던져 3초 동안 모두 묶고 피해를 줍니다. (공격력 240%)", L("Throw a huge net at the cursor, binding and damaging everything for 3s. (240% attack)", "マウス位置に巨大な網を投げ、3秒間すべてを縛ってダメージを与えます。(攻撃力240%)", "向鼠标位置抛出巨网，束缚并伤害所有敌人3秒。（攻击力240%）") },
        { "창의 벽", L("Wall of Spears", "槍の壁", "枪之墙") },
        { "투창 아홉 자루를 한 줄로 늘어세워 한꺼번에 던집니다. (공격력 320%씩)", L("Line up nine javelins and hurl them all at once. (320% attack each)", "投げ槍9本を一列に並べて一斉に投げます。(攻撃力320%ずつ)", "将九支标枪排成一列同时掷出。（每支攻击力320%）") },
        { "천 개의 화살", L("Thousand Arrows", "千本の矢", "千箭") },
        { "3초 동안 가까운 적들을 자동으로 겨눠 화살을 퍼붓습니다.", L("For 3s, automatically aim at nearby enemies and unleash a torrent of arrows.", "3秒間、近くの敵を自動で狙って矢を浴びせます。", "3秒内自动瞄准附近敌人倾泻箭雨。") },
        { "수은 폭풍", L("Quicksilver Storm", "水銀の嵐", "水银风暴") },
        { "수은 구슬 열여섯 개를 사방으로 튕겨 보냅니다.", L("Send sixteen quicksilver orbs bouncing in every direction.", "水銀玉16個を四方へ跳ね飛ばします。", "向四周弹射十六颗水银珠。") },
        { "블랙홀 플라스크", L("Black Hole Flask", "ブラックホールフラスコ", "黑洞烧瓶") },
        { "마우스 위치에 3초 동안 모든 것을 빨아들이는 소용돌이를 만든 뒤 크게 폭발합니다. (공격력 640%)", L("Create a vortex at the cursor that sucks everything in for 3s, then detonates. (640% attack)", "マウス位置に3秒間すべてを吸い込む渦を作り、大爆発します。(攻撃力640%)", "在鼠标位置制造吞噬一切的漩涡3秒，然后猛烈爆炸。（攻击力640%）") },
        { "불꽃 축제", L("Firework Festival", "花火大会", "烟花盛典") },
        { "3초 동안 적들 머리 위로 폭죽 스무 발을 터뜨립니다.", L("Burst twenty fireworks over enemies' heads for 3s.", "3秒間、敵の頭上で花火を20発打ち上げます。", "3秒内在敌人头顶绽放二十发烟花。") },
        { "와이어", L("Wire", "ワイヤー", "钢丝") },
        { "전투 함성!", L("War Cry!", "雄叫び！", "战吼！") },
        { "집중!", L("Focus!", "集中！", "专注！") },
        { "현자의 돌!", L("Philosopher's Stone!", "賢者の石！", "贤者之石！") },
        { "시간 역행!", L("Rewind!", "時間逆行！", "时光倒流！") },
        { "표식 초기화!", L("Mark reset!", "刻印リセット！", "印记重置！") },
        { "회피!", L("Dodge!", "回避！", "闪避！") },
        // v3.5 캐릭터 전용 레벨업 카드 (특수 능력)
        { "사냥의 기세", L("Hunter's Momentum", "狩りの勢い", "狩猎气势") },
        { "날아가는 검기", L("Flying Slash", "飛ぶ剣気", "飞行剑气") },
