        { "흰 갑옷과 금빛 장식, 푸른 망토. 움직이면 빛 잔상이 남고, 피격하면 맑은 방울 소리.", L("White armor, golden trim and a blue cape. Leaves light afterimages as you move, and a clear chime when hit.", "白い鎧と金の装飾、青いマント。動くと光の残像が残り、被弾すると澄んだ鈴の音。", "白色铠甲、金色装饰与蓝色披风。移动时留下光之残影，受击时响起清脆铃声。") },
        { "용기사", L("Dragon Knight", "竜騎士", "龙骑士") },
        { "용의 뿔 투구와 붉은 비늘 갑옷. 불씨 오라가 감돌고, 처치하면 불꽃이 튀며 필살기에 용의 포효가 울립니다.", L("A dragon-horned helm and red scale armor. An ember aura surrounds you, kills spark flames, and your ultimate roars like a dragon.", "竜の角の兜と赤い鱗の鎧。火の粉のオーラが漂い、倒すと火花が散り、必殺技で竜の咆哮が響きます。", "龙角头盔与红鳞铠甲。周身环绕火星光环，击杀时火花四溅，必杀技响起龙啸。") },
        { "모래 도적", L("Sand Thief", "砂の盗賊", "沙之盗贼") },
        { "모래빛 두건. 피격 소리가 가벼워집니다.", L("A sand-colored hood. Your hurt sound becomes lighter.", "砂色のフード。被弾音が軽くなります。", "沙色兜帽。受击声变得轻快。") },
        { "밤까마귀", L("Night Raven", "夜烏", "夜鸦") },
        { "검은 두건과 붉은 목도리, 하얗게 빛나는 눈. 피격하면 까마귀 날갯짓 소리.", L("A black hood, a red scarf and glowing white eyes. The flap of raven wings when hit.", "黒いフードと赤いマフラー、白く光る目。被弾するとカラスの羽ばたきの音。", "黑兜帽、红围巾与发白光的眼睛。受击时发出乌鸦振翅声。") },
        { "닌자", L("Ninja", "忍者", "忍者") },
        { "남색 복면과 길게 휘날리는 붉은 목도리. 움직이면 그림자 잔상, 피격하면 연기 소리.", L("A navy mask and a long, fluttering red scarf. Shadow afterimages as you move, and a puff of smoke when hit.", "紺の覆面と長くなびく赤いマフラー。動くと影の残像、被弾すると煙の音。", "藏青面罩与长长飘扬的红围巾。移动时留下影之残影，受击时发出烟雾声。") },
        { "그림자 군주", L("Shadow Lord", "影の君主", "暗影君主") },
        { "허공의 보랏빛 망토와 빛나는 분홍 눈. 어둠의 오라가 감돌고, 처치하면 그림자가 흩어지며 필살기에 속삭임이 울립니다.", L("A void-purple cloak and glowing pink eyes. A dark aura surrounds you, kills scatter shadows, and your ultimate whispers.", "虚空の紫のマントと光るピンクの目。闇のオーラが漂い、倒すと影が散り、必殺技でささやきが響きます。", "虚空紫色斗篷与发光的粉色眼睛。周身环绕黑暗光环，击杀时暗影飘散，必杀技响起低语。") },
        { "가을 사냥꾼", L("Autumn Hunter", "秋の狩人", "秋之猎人") },
        { "단풍빛 두건. 피격 소리가 부드러워집니다.", L("A maple-colored hood. Your hurt sound becomes softer.", "紅葉色のフード。被弾音が柔らかくなります。", "枫叶色兜帽。受击声变得柔和。") },
        { "설원 궁수", L("Snowfield Archer", "雪原の弓手", "雪原弓手") },
        { "흰 모피 두건과 얼음빛 옷. 피격하면 얼음 부서지는 소리.", L("A white fur hood and ice-colored clothes. The crack of ice when hit.", "白い毛皮のフードと氷色の服。被弾すると氷が割れる音。", "白色毛皮兜帽与冰色衣服。受击时发出冰碎声。") },
        { "엘프 레인저", L("Elf Ranger", "エルフのレンジャー", "精灵游侠") },
        { "에메랄드 두건과 금빛 머리띠. 움직이면 나뭇잎 잔상, 피격하면 바람 소리.", L("An emerald hood and a golden circlet. Leafy afterimages as you move, and a gust of wind when hit.", "エメラルドのフードと金のサークレット。動くと木の葉の残像、被弾すると風の音。", "翡翠兜帽与金色头环。移动时留下叶之残影，受击时响起风声。") },
        { "태양의 궁수", L("Sun Archer", "太陽の弓手", "太阳弓手") },
        { "태양빛 두건과 흰 옷. 햇살 오라가 감돌고, 처치하면 빛이 터지며 필살기에 성가가 울립니다.", L("A sun-colored hood and white clothes. A sunlight aura surrounds you, kills burst with light, and your ultimate sings a hymn.", "太陽色のフードと白い服。陽光のオーラが漂い、倒すと光が弾け、必殺技で聖歌が響きます。", "阳光色兜帽与白衣。周身环绕阳光光环，击杀时光芒迸发，必杀技响起圣歌。") },
        { "초록 약사", L("Green Herbalist", "緑の薬師", "绿色药师") },
        { "약초빛 옷. 피격 소리가 보글거립니다.", L("Herb-green clothes. Your hurt sound bubbles.", "薬草色の服。被弾音がぶくぶく泡立ちます。", "药草色衣服。受击声咕嘟冒泡。") },
        { "역병 의사", L("Plague Doctor", "ペスト医師", "瘟疫医生") },
        { "검은 외투와 하얀 부리 가면. 피격하면 둔탁한 가면 소리.", L("A black coat and a white beak mask. A dull thud of the mask when hit.", "黒い外套と白いくちばしの仮面。被弾すると鈍い仮面の音。", "黑色外套与白色鸟嘴面具。受击时发出沉闷的面具声。") },
        { "수은 학자", L("Mercury Scholar", "水銀の学者", "水银学者") },
        { "은빛 외투와 푸른 고글. 움직이면 수은 잔상, 피격하면 유리 울림.", L("A silver coat and blue goggles. Mercury afterimages as you move, and a ringing of glass when hit.", "銀の外套と青いゴーグル。動くと水銀の残像、被弾するとガラスの響き。", "银色外套与蓝色护目镜。移动时留下水银残影，受击时响起玻璃声。") },
        { "진홍 외투와 금빛 머리. 붉은 돌 조각이 주위를 돌고, 처치하면 붉은 결정이 흩어지며 필살기에 신비로운 공명이 울립니다.", L("A crimson coat and golden hair. Red stone shards orbit you, kills scatter red crystals, and your ultimate resonates mysteriously.", "真紅の外套と金色の髪。赤い石の欠片が周りを回り、倒すと赤い結晶が散り、必殺技で神秘的な共鳴が響きます。", "深红外套与金发。红色石片环绕身边，击杀时红色结晶飞散，必杀技响起神秘共鸣。") },
        { "은장 리볼버", L("Silver Revolver", "銀装のリボルバー", "银饰左轮") },
        { "은으로 새긴 권총. 총알이 푸르스름한 은빛으로 날고, 총소리에 맑은 금속 울림이 더해집니다.", L("A pistol engraved in silver. Bullets fly in a bluish silver, and a clear metallic ring joins the gunshot.", "銀を刻んだ拳銃。弾が青みがかった銀色で飛び、銃声に澄んだ金属音が加わります。", "刻有银纹的手枪。子弹化作泛蓝银光，枪声中多了清脆金属回响。") },
        { "용의 숨결", L("Dragon's Breath", "竜の息吹", "龙之吐息") },
        { "붉은 금빛 권총. 총알이 불꽃색으로 날고, 쏠 때마다 불붙는 소리가 납니다. 진화한 무기에도 색과 소리가 이어집니다.", L("A red-gold pistol. Bullets fly in flame colors with an igniting sound on every shot. The color and sound carry over to evolved weapons.", "赤金の拳銃。弾が炎の色で飛び、撃つたびに着火の音がします。進化した武器にも色と音が引き継がれます。", "赤金手枪。子弹呈火焰色，每次射击都有点燃声。进化后的武器也会延续颜色与声音。") },
        { "푸른 서리검", L("Frostblade", "青霜の剣", "蓝霜剑") },
        { "얼음빛 칼날. 베기가 서릿빛으로 빛나고 맑은 울림이 더해집니다.", L("An icy blade. Slashes glow with frost and a clear ring joins them.", "氷色の刃。斬撃が霜色に光り、澄んだ響きが加わります。", "冰色刀刃。斩击闪耀霜光，伴随清脆回响。") },
        { "흑요석 마검", L("Obsidian Demonblade", "黒曜の魔剣", "黑曜魔剑") },
        { "검보랏빛 마검. 베기가 보랏빛으로 물들고 번개 튀는 소리가 섞입니다.", L("A dark purple demon blade. Slashes turn violet with crackling lightning.", "黒紫の魔剣。斬撃が紫に染まり、稲妻の弾ける音が混じります。", "暗紫魔剑。斩击染成紫色，夹杂雷电噼啪声。") },
        { "황금 표창", L("Golden Stars", "黄金の手裏剣", "黄金飞镖") },
        { "금으로 만든 표창. 금빛으로 날고 반짝이는 소리가 납니다.", L("Throwing stars made of gold. They fly golden with a glittering sound.", "金でできた手裏剣。金色に飛び、きらめく音がします。", "黄金打造的飞镖。化作金光飞行，发出闪烁声。") },
        { "혈월 표창", L("Blood Moon Stars", "血月の手裏剣", "血月飞镖") },
        { "핏빛 초승달 표창. 붉게 날고 날카로운 베기 소리가 섞입니다.", L("Blood-red crescent stars. They fly red with a sharp slicing sound.", "血色の三日月の手裏剣。赤く飛び、鋭い斬撃音が混じります。", "血色新月飞镖。化作红光飞行，夹杂锐利斩击声。") },
        { "은빛 활", L("Silver Bow", "銀の弓", "银弓") },
        { "은으로 감은 활. 화살이 은빛으로 날고 시위 소리가 맑아집니다.", L("A bow wrapped in silver. Arrows fly silver and the string rings clearer.", "銀を巻いた弓。矢が銀色に飛び、弦の音が澄みます。", "缠银之弓。箭矢化作银光，弓弦声更清脆。") },
        { "세계수 활", L("World Tree Bow", "世界樹の弓", "世界树之弓") },
        { "살아 있는 나무 활. 화살이 초록빛으로 날고 바람과 방울 소리가 섞입니다.", L("A bow of living wood. Arrows fly green with wind and chimes.", "生きた木の弓。矢が緑色に飛び、風と鈴の音が混じります。", "活木之弓。箭矢化作绿光，夹杂风声与铃声。") },
        { "수정 플라스크", L("Crystal Flask", "水晶のフラスコ", "水晶烧瓶") },
        { "투명한 수정 플라스크. 폭발이 맑게 빛나고 유리 울림이 더해집니다.", L("A clear crystal flask. Explosions shine clear with a ringing of glass.", "透明な水晶のフラスコ。爆発が澄んで光り、ガラスの響きが加わります。", "透明水晶烧瓶。爆炸闪耀清光，伴随玻璃回响。") },
        { "용암 플라스크", L("Lava Flask", "溶岩のフラスコ", "熔岩烧瓶") },
        { "끓어오르는 용암 플라스크. 폭발이 주황빛으로 물들고 묵직한 폭음이 섞입니다.", L("A boiling lava flask. Explosions turn orange with a heavy boom.", "煮えたぎる溶岩のフラスコ。爆発が橙色に染まり、重い爆音が混じります。", "沸腾的熔岩烧瓶。爆炸染成橙色，夹杂沉重爆鸣。") },
        { "푸른 불꽃", L("Blue Flame", "青い炎", "蓝焰") },
        { "명중 불꽃 · 처치 효과 · 코인 반짝임이 푸른 불꽃으로 바뀝니다.", L("Hit sparks, kill effects and coin glitter turn into blue flames.", "命中の火花・撃破エフェクト・コインのきらめきが青い炎に変わります。", "命中火花、击杀特效与金币闪光变为蓝色火焰。") },
        { "벚꽃", L("Cherry Blossom", "桜", "樱花") },
        { "명중하면 분홍 불꽃, 적이 쓰러지면 벚꽃잎이 흩날립니다. 코인 소리가 맑아집니다.", L("Pink sparks on hit, cherry petals scatter when enemies fall. Coin sounds become clearer.", "命中するとピンクの火花、敵が倒れると桜の花びらが舞います。コインの音が澄みます。", "命中时粉色火花，敌人倒下时樱花瓣飞舞。金币声更清脆。") },
        { "뇌전", L("Thunder", "雷電", "雷电") },
        { "명중하면 노란 전기, 적이 쓰러지면 작은 번개가 칩니다. 코인에 전기 튀는 소리.", L("Yellow sparks on hit, small lightning strikes when enemies fall. Coins crackle with electricity.", "命中すると黄色い電気、敵が倒れると小さな雷が落ちます。コインに電気の弾ける音。", "命中时黄色电光，敌人倒下时落下小闪电。金币带有电流噼啪声。") },
        { "별의 축복", L("Starlight Blessing", "星の祝福", "星辰祝福") },
        { "명중 불꽃이 무지갯빛으로 바뀌고, 적이 쓰러지면 별이 터지며 맑은 종소리가 울립니다. 코인은 별가루로 반짝입니다.", L("Hit sparks turn rainbow, enemies burst into stars with a clear bell when they fall, and coins glitter with stardust.", "命中の火花が虹色になり、敵が倒れると星が弾けて澄んだ鐘の音が響きます。コインは星屑できらめきます。", "命中火花变为彩虹色，敌人倒下时星光迸发并响起清脆钟声。金币闪耀星尘。") },
        // 1.8.4 무기에 맞게 실시간으로
        { "지금 무기에는 효과가 없습니다", L("No effect with your current weapon", "今の武器には効果がありません", "对当前武器无效") },
        { "지금 무기에는 맞지 않아 대신 단계마다 무기 피해 +6%", L("Doesn't fit your current weapon, so it grants +6% weapon damage per level instead", "今の武器に合わないため、代わりに段階ごとに武器ダメージ +6%", "不适合当前武器，改为每级武器伤害 +6%") },
    };
}
